// Runtime rules for Blender library materials (look pass, requests from the willow canopy pass,
// commit c277388). GLTFLoader's defaults don't match how these are painted:
//   - MAT_willow_bark and the vertex-coloured kit materials (MAT_vc_*, the willow strands among them)
//     carry their baked AO and gradients in vertex colours: vertexColors on;
//   - MAT_vc_foliage (the crown's leaf cards) is a cut-out: alphaTest 0.45, both sides, drawn with
//     the solid things (no blending, writes depth), so cards sort and shadow correctly.
// The zone loader (P3) and the turntable's binder call this on every library material they keep.
import * as THREE from "three";

// Leaf cards and crowns dissolve (screen-door dither) within ~1.6 m of the camera, so a camera
// backed into a tree never fills the screen with leaves (pilot review fix 8). Chained after any
// patch the material already has; one more program variant per material.
export function nearFade(m, near = 0.5, far = 1.6) {
  if (m.userData.nearFade) return m;
  m.userData.nearFade = true;
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.fragmentShader = sh.fragmentShader.replace(
      "#include <clipping_planes_fragment>",
      `#include <clipping_planes_fragment>
      {
        float nd = length( vViewPosition );
        if ( nd < ${far.toFixed(2)} ) {
          float h = fract( 52.9829189 * fract( dot( gl_FragCoord.xy, vec2( 0.06711056, 0.00583715 ) ) ) );
          if ( h > smoothstep( ${near.toFixed(2)}, ${far.toFixed(2)}, nd ) ) discard;
        }
      }`,
    );
  };
  m.customProgramCacheKey = () => `${prevKey.call(m)}|near`;
  m.needsUpdate = true;
  return m;
}

export function libraryMaterial(m, geo) {
  const n = m?.name || "";
  if (!/^MAT_(vc_|willow_)/.test(n)) return m;
  if (n === "MAT_willow_bark" || n.startsWith("MAT_vc_") || /strand/i.test(n)) {
    if (!geo || geo.attributes.color) m.vertexColors = true;
  }
  if (n === "MAT_vc_foliage") {
    m.alphaTest = 0.45;
    m.side = THREE.DoubleSide;
    m.transparent = false;
    m.depthWrite = true;
    m.blending = THREE.NormalBlending;
  }
  m.needsUpdate = true;
  return m;
}
