// Welcome plaza (the "gate" room), v2: the visuals are the Blender zone zon_gate.glb (loaded by
// zones/runtime.js); this file registers the gameplay the legacy builder registered, from code
// constants, in the same order at the same point of the build (zones/legacy-gate.js stays the
// fallback), and wires the zone's moving parts, screens and halos once the GLB is in.
import * as THREE from "three";
import { mailFlag } from "../anim/props.js";
import { mosaicTexture, bannerTexture } from "./legacy-gate.js";

const P = [0, 3]; // the plaza's middle, in the gate room (legacy-gate.js)
const LAMP_DEG = [35, 90, 145, 215, 270, 325];
// obstacle tops, exported with the zone (zon_gate COL_ extras): no raycast measuring against
// whatever happens to be drawn (REBUILD-PLAN 6.1.3)
const TOP = { lamp: 3.36, bench: 1.0, topiary: 2.66, arch: 3.21, mailbox: 1.8, sign: 2.33 };

// INTERIORS.gate, data only: circles, bench walls, seats and the mailbox, exactly as legacy
export function interior(room) {
  const circle = (lx, lz, r, top) => {
    const p = this.toWorld(room, lx, 0, lz);
    this.addCircle(p.x, p.z, r);
    this.circles[this.circles.length - 1].top = top;
  };
  for (const deg of LAMP_DEG) {
    const a = THREE.MathUtils.degToRad(deg);
    circle(P[0] + Math.sin(a) * 5.0, P[1] + Math.cos(a) * 5.0, 0.2, TOP.lamp);
  }
  for (const s of [-1, 1]) {
    const bx = s * 3.35;
    const a = this.toWorld(room, P[0] + bx + s * 0.28, 0, P[1] - 0.9);
    const b = this.toWorld(room, P[0] + bx + s * 0.28, 0, P[1] + 0.9);
    this.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: TOP.bench, room: "" });
    for (const sz of [-0.42, 0.42]) this.seat(room, [P[0] + bx, P[1] + sz], -s * Math.PI / 2, 0.5, "sit by the heart ♡");
  }
  for (const s of [-1, 1]) circle(s * 3.1, -9.3, 0.45, TOP.topiary);
  circle(-1.7, -9.5, 0.3, TOP.arch);
  circle(1.7, -9.5, 0.3, TOP.arch);
  circle(2.5, 8.6, 0.4, TOP.mailbox);
  this.interact(room, { id: "mailbox", label: "check the mailbox (notifications)", local: [1.9, 0, 7.6], radius: 1.8, action: { type: "click", selector: "#notificationsBtn" } });
  circle(-2.7, 8.6, 0.3, TOP.sign);
  room.zoneV2 = true;
}

// once zon_gate.glb is in: what moves, the screens, the halos
export function wire({ world, root, nodes, kit, anims, camera }) {
  const N = nodes.gate;
  const room = world.rooms.get("gate");
  if (!N || !room) return;
  const node = (name) => N.get(name) || null;
  // (everything that moves works in the world's frame: its rest pose is kept)
  const live = (o) => {
    if (!o) return null;
    root.attach(o);
    o.userData.zoneLive = true;
    o.userData.rest = { p: o.position.clone(), q: o.quaternion.clone() };
    return o;
  };
  const centre = new THREE.Vector3();
  room.group.getWorldPosition(centre);
  const plaza = world.toWorld(room, P[0], 0, P[1]); // (0, 0, 70.5)
  const turn = room.group.rotation.y; // the room stands turned round (-PI)
  const local = (x, y, z, out) => out.set(x, y, z).applyAxisAngle(UP, turn).add(plaza);
  const near = (cam) => cam.distanceToSquared(centre) < 60 * 60;
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  const v = new THREE.Vector3();

  // ---- screens: the mosaic, the banner, the welcome sign ------------------------------------
  const flip = (t) => {
    t.flipY = false;
    t.needsUpdate = true;
    return t;
  };
  const mosaic = node("SCREEN_mosaic__0");
  if (mosaic) mosaic.material = new THREE.MeshStandardMaterial({ map: flip(mosaicTexture(kit.mulberry)), alphaTest: 0.5, roughness: 0.6, flatShading: false });
  const banner = new THREE.MeshBasicMaterial({ map: flip(bannerTexture()), alphaTest: 0.5 });
  for (const n of ["SCREEN_banner_front__0", "SCREEN_banner_back__0"]) if (node(n)) node(n).material = banner;
  const screen = kit.makeScreen(1.8, 1.0, { placeholder: "welcome home ♡", border: "#ff8fb1" });
  flip(screen.mesh.material.map);
  screen.draw({ title: "˗ˏˋ TOTO&DODO ˎˊ˗", lines: "forever and always ♡", center: true, foot: "open anything that sparkles ✦" });
  for (const n of ["SCREEN_sign_front__0", "SCREEN_sign_back__0"]) if (node(n)) node(n).material = screen.mesh.material;
  for (const n of ["SCREEN_mosaic__0", "SCREEN_banner_front__0", "SCREEN_banner_back__0", "SCREEN_sign_front__0", "SCREEN_sign_back__0"]) if (node(n)) node(n).castShadow = false;

  // ---- halos: the lamps, the arch lanterns (as legacy's glow sprites), the crystal heart ------
  for (const [re, size] of [[/^SOCK_lamp__\d+$/, 1.8], [/^SOCK_archlamp__\d+$/, 1.2]])
    for (const [name, o] of N) {
      if (!re.test(name)) continue;
      const sp = kit.glowSprite("#ffd08a", size);
      o.getWorldPosition(sp.position);
      root.add(sp);
    }
  const halo = kit.glowSprite("#ff9fc4", 2.8);
  delete halo.userData.glow;
  node("SOCK_halo__0")?.getWorldPosition(halo.position);
  root.add(halo);

  // ---- the crystal heart: bob and spin, the three mini hearts orbiting, motes spiralling up ---
  const bob = live(node("ANIM_bld_gate_crystalheart_bob__0"));
  const heart = live(node("ANIM_bld_gate_crystalheart_heart__0"));
  const minis = [0, 1, 2].map((k) => live(node(`ANIM_bld_gate_crystalheart_mini_${k}__0`)));
  const mote = node("ANIM_bld_gate_crystalheart_mote__0");
  let motes = null;
  if (mote) {
    motes = new THREE.InstancedMesh(mote.geometry, mote.material, 34);
    motes.frustumCulled = false;
    motes.castShadow = false;
    motes.userData.zoneLive = true;
    motes.userData.glowMoves = true; // (their glow cards follow them: render/glow.js)
    mote.visible = false;
    root.add(motes);
  }
  const moteAt = Array.from({ length: 34 }, (_, k) => ({ ph: k / 34, a: k * 2.4 }));
  const haloAt = new THREE.Vector3();
  const m4 = new THREE.Matrix4();
  const one = new THREE.Vector3(1, 1, 1);
  const sc = new THREE.Vector3();
  anims.push((t, dt, cam) => {
    if (!near(cam)) return;
    const y = 4.7 + Math.sin(t * 1.2) * 0.18;
    if (bob) bob.position.y = bob.userData.rest.p.y + (y - 4.7);
    if (heart) {
      heart.position.copy(heart.userData.rest.p).setY(heart.userData.rest.p.y + (y - 4.7));
      heart.quaternion.copy(heart.userData.rest.q).multiply(q.setFromAxisAngle(UP, t * 0.6));
    }
    halo.position.y = y;
    const dc = cam.distanceTo(halo.getWorldPosition(haloAt));
    halo.material.opacity = (0.3 + Math.sin(t * 2) * 0.08) * THREE.MathUtils.smoothstep(dc, 5, 12);
    minis.forEach((m, k) => {
      if (!m) return;
      const a = t * 0.9 + (k / 3) * Math.PI * 2;
      local(Math.sin(a) * 1.7, 4.7 + Math.sin(t * 1.6 + k) * 0.4, Math.cos(a) * 1.7, m.position);
      m.quaternion.setFromAxisAngle(UP, -a + turn);
    });
    if (motes) {
      moteAt.forEach((p, i) => {
        const u = (t * 0.12 + p.ph) % 1;
        const a = p.a + u * 7;
        const r = 2.6 * (1 - u) + 0.3;
        local(Math.sin(a) * r, 0.2 + u * 5.2, Math.cos(a) * r, v);
        m4.compose(v, q.identity(), sc.setScalar(Math.sin(u * Math.PI) + 0.01));
        motes.setMatrixAt(i, m4);
      });
      motes.instanceMatrix.needsUpdate = true;
    }
  });

  // ---- petals drifting down over the plaza, and the five butterflies ---------------------------
  const petal = node("ANIM_zon_gate_petal");
  if (petal) {
    const R = kit.mulberry(86);
    const petals = new THREE.InstancedMesh(petal.geometry, petal.material, 70);
    petals.frustumCulled = false;
    petals.castShadow = false;
    petals.userData.zoneLive = true;
    petals.userData.lookGlow = false;
    petal.visible = false;
    root.add(petals);
    const ps = Array.from({ length: 70 }, () => ({ x: (R() - 0.5) * 12, y: R() * 7, z: (R() - 0.5) * 12, s: 0.25 + R() * 0.3, ph: R() * 6 }));
    anims.push((t, dt, cam) => {
      if (!near(cam)) return;
      dt = Math.min(0.1, dt);
      ps.forEach((p, i) => {
        p.y -= dt * p.s;
        if (p.y < 0.08) {
          p.y = 6.5 + R();
          p.x = (R() - 0.5) * 12;
          p.z = (R() - 0.5) * 12;
        }
        local(p.x + Math.sin(t * 0.9 + p.ph) * 0.4, p.y, p.z + Math.cos(t * 0.7 + p.ph) * 0.4, v);
        m4.compose(v, q.setFromEuler(e.set(t * 1.3 + p.ph, t + p.ph, t * 0.7)), one);
        petals.setMatrixAt(i, m4);
      });
      petals.instanceMatrix.needsUpdate = true;
    });
  }
  const flies = ["pink", "butter", "lilac", "sky", "cream"].map((c, k) => {
    const body = live(node(`ANIM_bld_gate_butterfly_${c}_fly__0`));
    if (!body) return null;
    const wings = ["l", "r"].map((s) => node(`ANIM_bld_gate_butterfly_${c}_wing_${s}__0`)).filter(Boolean);
    for (const w of wings) {
      w.userData.zoneLive = true;
      w.userData.rest = { q: w.quaternion.clone() };
    }
    return { body, wings, ph: k * 1.9, r: 3.6 + (k % 3) * 0.9, sp: 0.35 + k * 0.06, lx: 0, lz: 0 };
  });
  anims.push((t, dt, cam) => {
    if (!near(cam)) return;
    for (const b of flies) {
      if (!b) continue;
      const a = t * b.sp + b.ph;
      const x = Math.sin(a) * b.r + Math.sin(a * 2.7) * 0.4;
      const z = Math.cos(a * 1.1) * b.r;
      const ry = Math.atan2(x - b.lx, z - b.lz);
      b.lx = x;
      b.lz = z;
      local(x, 0.9 + Math.sin(a * 2.3) * 0.4, z, b.body.position);
      b.body.quaternion.setFromAxisAngle(UP, ry + turn);
      const flap = 0.2 + Math.abs(Math.sin(t * 14 + b.ph)) * 1.1;
      b.wings.forEach((w, i) => w.quaternion.copy(w.userData.rest.q).multiply(q.setFromAxisAngle(Z, i ? -flap : flap)));
    }
  });

  // ---- the six heart balloons on the arch, each on its own string ----------------------------------
  const balloons = [0, 1, 2, 3, 4, 5].map((i) => {
    const b = live(node(`ANIM_zon_gate_balloon_${i}`));
    // (world +x is the arch's local -x: balloons 0-2 are legacy s = -1, 3-5 s = +1)
    return b && { b, ph: (i % 3) + (i < 3 ? -1 : 1) };
  });
  anims.push((t, dt, cam) => {
    if (!near(cam)) return;
    for (const p of balloons) {
      if (!p) continue;
      const r = p.b.userData.rest;
      p.b.position.copy(r.p).setY(r.p.y + Math.sin(t * 1.3 + p.ph) * 0.08);
      p.b.quaternion.copy(r.q).multiply(q.setFromEuler(e.set(0, Math.sin(t * 0.6 + p.ph) * 0.4, Math.sin(t * 0.9 + p.ph) * 0.12)));
    }
  });

  // ---- the mailbox: its flag is up while something is unread, the letter bobs over it --------------
  const flag = live(node("ANIM_bld_gate_mailbox_flag__0"));
  const letter = live(node("ANIM_bld_gate_mailbox_letter__0"));
  const marker = live(node("ANIM_bld_gate_mailbox_marker__0"));
  room.mailFlag = flag;
  room.mailLetter = letter;
  let flagA = 0;
  anims.push((t, dt) => {
    const unread = room.unread || 0;
    flagA += ((unread ? 0 : -1.5) - flagA) * 0.1;
    if (flag && !mailFlag(flag, unread, dt, { mode: "rest", restQ: flag.userData.rest.q, restP: flag.userData.rest.p })) flag.quaternion.copy(flag.userData.rest.q).multiply(q.setFromAxisAngle(X, flagA));
    if (letter) {
      letter.visible = unread > 0;
      letter.position.copy(letter.userData.rest.p).setY(1.85 + Math.sin(t * 3) * 0.1);
      letter.quaternion.copy(letter.userData.rest.q).multiply(q.setFromAxisAngle(UP, t));
    }
    if (marker) {
      marker.position.copy(marker.userData.rest.p).setY(2.3 + Math.sin(t * 2.5) * 0.12);
      marker.quaternion.copy(marker.userData.rest.q).multiply(q.setFromAxisAngle(UP, t * 1.5));
    }
  });
  void camera;
}

const UP = new THREE.Vector3(0, 1, 0);
const X = new THREE.Vector3(1, 0, 0);
const Z = new THREE.Vector3(0, 0, 1);
