// Welcome plaza (the "gate" room): the LEGACY builder, carved verbatim out of world.js
// (INTERIORS.gate, P0). Nothing here changed but the indentation: the same calls in the same
// order, the same mulberry streams (84 mosaic, 85 flower ring, 86 petals, 87 rose arch), the
// same objects, names, colliders, seats and interactables. It still runs with the World as
// `this`, exactly as the INTERIORS methods do; world.js hands in its module-local helpers
// (kit), so there is no import cycle. Picked by zones/registry.js while ZONES.gate.impl is
// "legacy". A v2 zone (GLB visuals) replaces this file; it must register the same gameplay data.
import * as THREE from "three";
import { mailFlag } from "../anim/props.js";
import { texture, textCanvas, FONT } from "../textures.js";
import { bakeWhenSettled } from "../bake.js";

const xz = (v) => [v.x, v.z];

// the mosaic heart under your feet where you arrive (a canvas: the legacy inlay and the v2 zone's
// SCREEN_mosaic both show it), drawn from its own stream (mulberry 84)
export function mosaicTexture(mulberry) {
  const S = 1024;
  const c = document.createElement("canvas");
  c.width = c.height = S;
  const x = c.getContext("2d");
  const R = mulberry(84);
  const N = 34;
  const cell = S / N;
  const heartAt = (u, v) => {
    const X = u * 1.55;
    const Y = v * 1.55 + 0.2;
    return (X * X + Y * Y - 1) ** 3 - X * X * Y * Y * Y <= 0;
  };
  x.save();
  x.beginPath();
  x.arc(S / 2, S / 2, S * 0.4, 0, Math.PI * 2);
  x.clip();
  x.fillStyle = "#fffaf6";
  x.fillRect(0, 0, S, S);
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const u = ((i + 0.5) * cell - S / 2) / (S * 0.4);
      const v = -((j + 0.5) * cell - S / 2) / (S * 0.4);
      const inH = heartAt(u, v);
      const step = cell / (S * 0.4);
      const edge = !inH && [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, b]) => heartAt(u + a * step, v + b * step));
      x.fillStyle = inH
        ? ["#ff8fb1", "#f2709a", "#ff9fc0", "#e8638f", "#ffb3cf"][Math.floor(R() * 5)]
        : edge
          ? ["#ffd166", "#ffe08a", "#f2c14a"][Math.floor(R() * 3)]
          : ["#f6ede6", "#efe4ec", "#fbf3ee", "#e8dde6", "#f3e2ea"][Math.floor(R() * 5)];
      x.beginPath();
      x.roundRect(i * cell + 2.5, j * cell + 2.5, cell - 5, cell - 5, 5);
      x.fill();
    }
  }
  x.restore();
  // the ring of words round it
  x.lineWidth = S * 0.085;
  x.strokeStyle = "#c7b0f5";
  x.beginPath();
  x.arc(S / 2, S / 2, S * 0.445, 0, Math.PI * 2);
  x.stroke();
  for (const r of [0.4, 0.49]) {
    x.lineWidth = 7;
    x.strokeStyle = "#ffd166";
    x.beginPath();
    x.arc(S / 2, S / 2, S * r, 0, Math.PI * 2);
    x.stroke();
  }
  const words = "  ˚₊‧ welcome home ‧₊˚   ♡   toto & dodo   ♡   forever & always   ♡  ";
  x.font = `700 46px ${FONT}`;
  x.fillStyle = "#fffaf6";
  x.textAlign = "center";
  x.textBaseline = "middle";
  const chars = [...words];
  const total = chars.reduce((a, ch) => a + x.measureText(ch).width, 0);
  const rr = S * 0.445;
  // spread the words evenly all the way round
  const k = (Math.PI * 2 * rr) / total;
  let ang = -Math.PI / 2;
  for (const ch of chars) {
    const w = x.measureText(ch).width * k;
    ang += w / 2 / rr;
    x.save();
    x.translate(S / 2 + Math.cos(ang) * rr, S / 2 + Math.sin(ang) * rr);
    x.rotate(ang + Math.PI / 2);
    x.fillText(ch, 0, 2);
    x.restore();
    ang += w / 2 / rr;
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

// the banner over the rose arch (legacy plane and the v2 SCREEN_banner faces)
export function bannerTexture() {
  const { ctx, tex } = textCanvas(1024, 256);
  ctx.clearRect(0, 0, 1024, 256);
  const grd = ctx.createLinearGradient(0, 0, 1024, 0);
  grd.addColorStop(0, "#ff8fb1");
  grd.addColorStop(1, "#b79be8");
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.roundRect(10, 30, 1004, 196, 98);
  ctx.fill();
  ctx.lineWidth = 8;
  ctx.strokeStyle = "#fffaf6";
  ctx.setLineDash([16, 12]);
  ctx.beginPath();
  ctx.roundRect(30, 50, 964, 156, 78);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = "#fffaf6";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = `800 84px ${FONT}`;
  ctx.fillText("toto ♡ dodo", 512, 118);
  ctx.font = `700 34px ${FONT}`;
  ctx.fillText("˚₊‧ welcome to our island ‧₊˚", 512, 182);
  tex.needsUpdate = true;
  return tex;
}

export function interior(room, kit) {
  const { add, box, cyl, std, glow, glowSprite, heartGeo, stonePatio, marker, mulberry, buildWalkways, makeScreen, photoFrame, UP } = kit;
  const g = room.group;
  const wood = std("#ffffff", { map: texture("wood", ["#fff3ea", "#e8d4c8"]) });
  const iron = std("#5b4a5a");
  const P = [0, 3]; // the plaza's middle: where you arrive
  const anim = (fn) => this.animated.push(fn);
  // the moving bits only bother when someone could see them
  const here = new THREE.Vector3();
  g.getWorldPosition(here);
  const near = () => !this.viewer || this.viewer.distanceTo(here) < 60;

  // ---- the plaza: a round stone patio with a mosaic heart where you appear ------------
  const plaza = new THREE.Group();
  plaza.position.set(P[0], 0, P[1]);
  g.add(plaza);
  stonePatio(plaza, 1.72, 4.6, ["#f2e6ec", "#cdb8c4"]); // (round the mosaic heart)
  {
    const tex = mosaicTexture(mulberry);
    const inlay = add(plaza, new THREE.CircleGeometry(2.2, 72), new THREE.MeshStandardMaterial({ map: tex, alphaTest: 0.5, roughness: 0.6 }), 0, 0.075, 0, { rx: -Math.PI / 2, cast: false });
    inlay.rotation.z = Math.PI; // the heart stands upright as you walk in from the island
  }

  // ---- a big crystal heart floating over the middle, with motes spiralling up --------
  {
    const crystal = new THREE.MeshStandardMaterial({ color: "#ffc4dc", emissive: "#ff5c9a", emissiveIntensity: 0.55, roughness: 0.15, metalness: 0.1, flatShading: true, transparent: true, opacity: 0.93 });
    const heart = add(plaza, heartGeo(1.5), crystal, 0, 4.7, 0, { cast: false });
    // (a soft halo: it stays small and fades as the camera comes close, so it never
    // washes over the whole view and makes the gate look brighter than everywhere else)
    const halo = glowSprite("#ff9fc4", 2.8);
    delete halo.userData.glow;
    halo.position.y = 4.7;
    const haloAt = new THREE.Vector3();
    plaza.add(halo);
    const minis = [glow.pink, glow.warm, glow.magic].map((m) => add(plaza, heartGeo(0.38), m, 0, 4, 0, { cast: false }));
    const moteGeo = new THREE.IcosahedronGeometry(0.045, 0);
    const motes = Array.from({ length: 34 }, (_, k) => ({ m: add(plaza, moteGeo, k % 3 ? glow.warm : glow.pink, 0, 0, 0, { cast: false }), ph: k / 34, a: k * 2.4 }));
    anim((t) => {
      if (!near()) return;
      heart.position.y = 4.7 + Math.sin(t * 1.2) * 0.18;
      heart.rotation.y = t * 0.6;
      halo.position.y = heart.position.y;
      const cam = this.cameraPos;
      const dc = cam ? cam.distanceTo(halo.getWorldPosition(haloAt)) : 99;
      halo.material.opacity = (0.3 + Math.sin(t * 2) * 0.08) * THREE.MathUtils.smoothstep(dc, 5, 12);
      crystal.emissiveIntensity = 0.5 + Math.sin(t * 2) * 0.15;
      minis.forEach((m, k) => {
        const a = t * 0.9 + (k / 3) * Math.PI * 2;
        m.position.set(Math.sin(a) * 1.7, 4.7 + Math.sin(t * 1.6 + k) * 0.4, Math.cos(a) * 1.7);
        m.rotation.y = -a;
      });
      for (const p of motes) {
        const u = (t * 0.12 + p.ph) % 1;
        const a = p.a + u * 7;
        const r = 2.6 * (1 - u) + 0.3;
        p.m.position.set(Math.sin(a) * r, 0.2 + u * 5.2, Math.cos(a) * r);
        p.m.scale.setScalar(Math.sin(u * Math.PI) + 0.01);
      }
    });
  }

  // ---- lamp posts round the edge, strung together with fairy lights ------------------
  const lampAt = [35, 90, 145, 215, 270, 325].map((deg) => {
    const a = THREE.MathUtils.degToRad(deg);
    return [Math.sin(a) * 5.0, Math.cos(a) * 5.0];
  });
  const tops = [];
  for (const [lx, lz] of lampAt) {
    const lamp = new THREE.Group();
    lamp.position.set(lx, 0, lz);
    lamp.rotation.y = Math.atan2(-lx, -lz) - Math.PI / 2; // lanterns lean in over the plaza
    plaza.add(lamp);
    add(lamp, cyl(0.07, 0.1, 3.1, 8), iron, 0, 1.55, 0);
    add(lamp, cyl(0.16, 0.2, 0.12, 8), iron, 0, 0.06, 0);
    add(lamp, new THREE.TorusGeometry(0.18, 0.025, 5, 12, Math.PI), iron, 0.18, 3.1, 0);
    add(lamp, box(0.28, 0.32, 0.28), glow.warm, 0.36, 2.88, 0, { cast: false });
    add(lamp, new THREE.ConeGeometry(0.24, 0.18, 4), iron, 0.36, 3.13, 0, { ry: Math.PI / 4 });
    const sp = glowSprite("#ffd08a", 1.8);
    sp.position.set(0.36, 2.88, 0);
    lamp.add(sp);
    tops.push(new THREE.Vector3(lx, 3.02, lz));
    this.addCircle(...xz(this.toWorld(room, P[0] + lx, 0, P[1] + lz)), 0.2);
  }
  {
    const bulbGeo = new THREE.IcosahedronGeometry(0.07, 0);
    const bulbs = [glow.warm, glow.pink, glow.magic];
    const wire = std("#6a5a6a");
    // round the sides only: none over the ways in and out, where they would hang
    // right across the view as you arrive
    for (let i = 0; i < tops.length; i++) {
      if (i === 2 || i === 5) continue;
      const a = tops[i];
      const b = tops[(i + 1) % tops.length];
      const n = 11;
      const pts = [];
      for (let k = 0; k <= n; k++) {
        const u = k / n;
        pts.push(new THREE.Vector3().lerpVectors(a, b, u).setY(a.y - Math.sin(u * Math.PI) * 0.4));
      }
      add(plaza, new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 24, 0.012, 4), wire, 0, 0, 0, { cast: false });
      for (let k = 1; k < n; k++) add(plaza, bulbGeo, bulbs[(i + k) % 3], pts[k].x, pts[k].y - 0.07, pts[k].z, { cast: false });
    }
  }

  // ---- two benches facing the heart --------------------------------------------------
  for (const s of [-1, 1]) {
    const bench = new THREE.Group();
    const bx = s * 3.35;
    bench.position.set(bx, 0, 0);
    bench.rotation.y = -s * Math.PI / 2; // front (local +z) towards the middle
    plaza.add(bench);
    add(bench, box(1.7, 0.08, 0.5), wood, 0, 0.46, 0);
    add(bench, box(1.7, 0.42, 0.06), wood, 0, 0.84, -0.24, { rx: -0.12 });
    for (const lx of [-0.75, 0.75]) {
      add(bench, box(0.08, 0.46, 0.46), iron, lx, 0.23, 0);
      add(bench, new THREE.TorusGeometry(0.12, 0.02, 4, 10, Math.PI), iron, lx, 0.62, 0.15, { ry: Math.PI / 2 });
    }
    add(bench, box(0.34, 0.3, 0.12), std(s < 0 ? "#f7b8cf" : "#c7b0f5"), -0.45, 0.66, -0.15, { rx: -0.25, rz: 0.15 });
    const a = this.toWorld(room, P[0] + bx + s * 0.28, 0, P[1] - 0.9);
    const b = this.toWorld(room, P[0] + bx + s * 0.28, 0, P[1] + 0.9);
    this.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: 1.0, room: "" });
    for (const sz of [-0.42, 0.42]) this.seat(room, [P[0] + bx, P[1] + sz], -s * Math.PI / 2, 0.5, "sit by the heart ♡");
  }

  // ---- a ring of flowers round the plaza (gaps where the paths come in) ---------------
  {
    const R = mulberry(85);
    const leafSpots = [];
    const blooms = [];
    for (let k = 0; leafSpots.length < 120 && k < 900; k++) {
      const a = R() * Math.PI * 2;
      const r = 5.25 + R() * 1.0;
      const lx = Math.sin(a) * r;
      const lz = Math.cos(a) * r;
      if (Math.abs(lx) < 1.7) continue; // the ways in and out
      if (lampAt.some(([px, pz]) => Math.hypot(px - lx, pz - lz) < 0.45)) continue;
      leafSpots.push([lx, lz, 0.7 + R() * 0.6]);
      const n = 2 + Math.floor(R() * 3);
      for (let j = 0; j < n; j++) blooms.push([lx + (R() - 0.5) * 0.3, 0.22 + R() * 0.14, lz + (R() - 0.5) * 0.3, R()]);
    }
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const col = new THREE.Color();
    const leaves = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.2, 0), std("#ffffff", { key: "spawnleaf" }), leafSpots.length);
    leafSpots.forEach(([lx, lz, k], i) => {
      m4.compose(new THREE.Vector3(lx, 0.1 * k, lz), q.setFromAxisAngle(UP, k * 7), new THREE.Vector3(k * 1.2, k * 0.75, k * 1.2));
      leaves.setMatrixAt(i, m4);
      leaves.setColorAt(i, col.set(["#6fb46a", "#5aa66a", "#8fc46a"][i % 3]));
    });
    const flowers = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.075, 0), std("#ffffff", { key: "spawnbloom" }), blooms.length);
    const tones = ["#ff8fb1", "#ffd166", "#fff7f2", "#c7b0f5", "#ff6f91", "#8fd3f0"];
    blooms.forEach(([lx, ly, lz, r], i) => {
      m4.compose(new THREE.Vector3(lx, ly, lz), q.setFromAxisAngle(UP, r * 6), new THREE.Vector3(1, 0.7, 1).multiplyScalar(0.8 + r * 0.6));
      flowers.setMatrixAt(i, m4);
      flowers.setColorAt(i, col.set(tones[Math.floor(r * tones.length)]));
    });
    for (const im of [leaves, flowers]) {
      im.castShadow = true;
      im.receiveShadow = true;
      plaza.add(im);
    }
  }

  // ---- petals drifting down over the plaza, and butterflies --------------------------
  {
    const R = mulberry(86);
    const N = 70;
    const petals = new THREE.InstancedMesh(new THREE.PlaneGeometry(0.11, 0.075), new THREE.MeshStandardMaterial({ color: "#ffffff", side: THREE.DoubleSide, roughness: 0.8 }), N);
    petals.frustumCulled = false;
    const col = new THREE.Color();
    const ps = Array.from({ length: N }, (_, i) => {
      petals.setColorAt(i, col.set(["#ffc4d8", "#ffd9e6", "#fff0f5", "#ffb3cf"][i % 4]));
      return { x: (R() - 0.5) * 12, y: R() * 7, z: (R() - 0.5) * 12, s: 0.25 + R() * 0.3, ph: R() * 6 };
    });
    plaza.add(petals);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const one = new THREE.Vector3(1, 1, 1);
    const v = new THREE.Vector3();
    const flies = ["#ff8fb1", "#ffd166", "#b79be8", "#8fd3f0", "#fff7f2"].map((c, k) => {
      const f = new THREE.Group();
      const wm = new THREE.MeshStandardMaterial({ color: c, side: THREE.DoubleSide, emissive: c, emissiveIntensity: 0.2 });
      const wings = [1, -1].map((s) => {
        const w = new THREE.Mesh(new THREE.CircleGeometry(0.1, 5).translate(0.1, 0, 0), wm);
        w.rotation.x = -Math.PI / 2;
        const piv = new THREE.Group();
        piv.scale.x = s;
        piv.add(w);
        f.add(piv);
        return piv;
      });
      plaza.add(f);
      return { f, wings, ph: k * 1.9, r: 3.6 + (k % 3) * 0.9, sp: 0.35 + k * 0.06 };
    });
    let last = 0;
    anim((t) => {
      const dt = Math.min(0.1, Math.max(0, t - last));
      last = t;
      if (!near()) return;
      ps.forEach((p, i) => {
        p.y -= dt * p.s;
        if (p.y < 0.08) {
          p.y = 6.5 + R();
          p.x = (R() - 0.5) * 12;
          p.z = (R() - 0.5) * 12;
        }
        v.set(p.x + Math.sin(t * 0.9 + p.ph) * 0.4, p.y, p.z + Math.cos(t * 0.7 + p.ph) * 0.4);
        m4.compose(v, q.setFromEuler(e.set(t * 1.3 + p.ph, t + p.ph, t * 0.7)), one);
        petals.setMatrixAt(i, m4);
      });
      petals.instanceMatrix.needsUpdate = true;
      for (const b of flies) {
        const a = t * b.sp + b.ph;
        const x = Math.sin(a) * b.r + Math.sin(a * 2.7) * 0.4;
        const z = Math.cos(a * 1.1) * b.r;
        b.f.rotation.y = Math.atan2(x - b.f.position.x, z - b.f.position.z);
        b.f.position.set(x, 0.9 + Math.sin(a * 2.3) * 0.4, z);
        const flap = 0.2 + Math.abs(Math.sin(t * 14 + b.ph)) * 1.1;
        b.wings[0].rotation.z = flap;
        b.wings[1].rotation.z = flap;
      }
    });
  }

  // ---- a cobbled walk from the plaza out to the gate ----------------------------------
  {
    const pts = [];
    for (let z = P[1] - 4.0; z >= -10.4; z -= 0.5) pts.push([0, z]);
    g.add(buildWalkways([{ pts, w: 2.4, pebbleFrom: 0.6 }], { seed: 11, space: g, meetPatios: true })); // (laid in the gate's own space)
  }

  // ---- the gate: a grand arch of roses with a banner, lanterns and balloons -----------
  const arch = new THREE.Group();
  arch.position.z = -9.5;
  g.add(arch);
  for (const s of [-1, 1]) {
    add(arch, box(0.34, 3.2, 0.34), wood, s * 1.7, 1.6, 0);
    add(arch, box(0.5, 0.18, 0.5), wood, s * 1.7, 0.09, 0);
    add(arch, box(0.46, 0.14, 0.46), wood, s * 1.7, 3.2, 0);
  }
  add(arch, new THREE.TorusGeometry(1.7, 0.16, 6, 20, Math.PI), wood, 0, 3.2, 0);
  {
    const R = mulberry(87);
    const leafM = std("#5aa66a");
    const roseM = [std("#ff8fb1"), std("#ff6f91"), std("#fff0f5"), std("#ffd166")];
    for (let i = 0; i < 46; i++) {
      const up = i < 16;
      const s = i % 2 ? 1 : -1;
      const a = R() * Math.PI;
      const px = up ? s * (1.7 + (R() - 0.5) * 0.3) : Math.cos(a) * 1.7;
      const py = up ? 0.4 + R() * 2.8 : 3.2 + Math.sin(a) * 1.7;
      add(arch, new THREE.IcosahedronGeometry(0.17, 0), leafM, px, py, (R() - 0.5) * 0.3, { cast: false });
      if (i % 3 !== 2) add(arch, new THREE.IcosahedronGeometry(0.1, 1), roseM[i % 4], px + (R() - 0.5) * 0.15, py + 0.08, 0.16 * (R() > 0.5 ? 1 : -1), { cast: false });
    }
    // lanterns hanging from the arch
    for (const s of [-1, 1]) {
      const lx = s * 1.0;
      add(arch, cyl(0.008, 0.008, 0.55, 3), iron, lx, 4.03, 0, { cast: false });
      add(arch, box(0.2, 0.26, 0.2), glow.warm, lx, 3.62, 0, { cast: false });
      add(arch, new THREE.ConeGeometry(0.17, 0.12, 4), iron, lx, 3.8, 0, { ry: Math.PI / 4, cast: false });
      const sp = glowSprite("#ffd08a", 1.2);
      sp.position.set(lx, 3.62, 0);
      arch.add(sp);
    }
  }
  // the banner over the top
  {
    const tex = bannerTexture();
    const bm = new THREE.MeshBasicMaterial({ map: tex, alphaTest: 0.5, toneMapped: false });
    for (const back of [false, true]) add(arch, new THREE.PlaneGeometry(3.8, 0.95), bm, 0, 5.25, back ? -0.03 : 0.03, { cast: false, ry: back ? Math.PI : 0 });
    for (const s of [-1, 1]) add(arch, cyl(0.03, 0.03, 0.42, 5), iron, s * 1.2, 4.75, 0, { cast: false });
  }
  // heart balloons tied to the posts
  {
    const tones = ["#ff8fb1", "#c7b0f5", "#ffd166", "#ff6f91", "#8fd3f0", "#ffb3cf"];
    const balloons = [];
    for (const s of [-1, 1]) {
      for (let k = 0; k < 3; k++) {
        const bx = s * (2.0 + k * 0.28);
        const by = 3.7 + k * 0.45;
        const m = new THREE.MeshStandardMaterial({ color: tones[k + (s > 0 ? 3 : 0)], roughness: 0.25, metalness: 0.05 });
        const b = add(arch, heartGeo(0.55), m, bx, by, 0.1, { cast: false });
        add(arch, cyl(0.004, 0.004, by - 2.1, 3), std("#ffffff"), bx - s * 0.1, (by + 1.6) / 2 - 0.1, 0.1, { cast: false });
        balloons.push({ b, by, ph: k + s });
      }
    }
    anim((t) => {
      if (!near()) return;
      for (const p of balloons) {
        p.b.position.y = p.by + Math.sin(t * 1.3 + p.ph) * 0.08;
        p.b.rotation.z = Math.sin(t * 0.9 + p.ph) * 0.12;
        p.b.rotation.y = Math.sin(t * 0.6 + p.ph) * 0.4;
      }
    });
  }
  // heart topiaries in pots either side of the gate
  for (const s of [-1, 1]) {
    const tx = s * 3.1;
    add(g, cyl(0.42, 0.32, 0.55, 10), std("#d9855a"), tx, 0.27, -9.3);
    add(g, cyl(0.45, 0.45, 0.08, 10), std("#e89a6e"), tx, 0.56, -9.3);
    add(g, cyl(0.05, 0.05, 0.6, 5), std("#7a5a44"), tx, 0.85, -9.3);
    const hedge = add(g, heartGeo(1.5), std("#5aa66a"), tx, 1.75, -9.3);
    hedge.scale.z = 0.6;
    const dot = std("#ff8fb1");
    for (let k = 0; k < 7; k++) add(g, new THREE.IcosahedronGeometry(0.05, 0), dot, tx + Math.sin(k * 2.3) * 0.5, 1.7 + Math.cos(k * 1.7) * 0.35, -9.3 + 0.24 * (k % 2 ? 1 : -1), { cast: false });
    this.addCircle(...xz(this.toWorld(room, tx, 0, -9.3)), 0.45);
  }
  this.addCircle(...xz(this.toWorld(room, -1.7, 0, -9.5)), 0.3);
  this.addCircle(...xz(this.toWorld(room, 1.7, 0, -9.5)), 0.3);

  // ---- the mailbox and the welcome sign, either side of the way onto the island -------
  const mb = new THREE.Group();
  mb.position.set(2.5, 0, 8.6);
  mb.rotation.y = 0.5;
  g.add(mb);
  add(mb, box(0.14, 1.1, 0.14), wood, 0, 0.55, 0);
  const boxMat = std("#e2557f");
  add(mb, box(0.55, 0.45, 0.8), boxMat, 0, 1.3, 0);
  add(mb, new THREE.CylinderGeometry(0.275, 0.275, 0.8, 10, 1, false, 0, Math.PI), boxMat, 0, 1.52, 0).rotation.set(Math.PI / 2, 0, 0);
  add(mb, heartGeo(0.22), std("#fff0f5"), 0.29, 1.35, 0, { ry: Math.PI / 2, cast: false });
  const flag = new THREE.Group();
  flag.position.set(0.3, 1.3, -0.2);
  mb.add(flag);
  add(flag, box(0.04, 0.5, 0.04), std("#ffd166"), 0, 0.25, 0);
  add(flag, box(0.04, 0.18, 0.25), std("#ffd166"), 0, 0.45, 0.12);
  room.mailFlag = flag;
  const letter = add(mb, box(0.3, 0.02, 0.2), glow.warm, 0, 1.8, 0, { cast: false });
  room.mailLetter = letter;
  anim((t, dt) => {
    const unread = room.unread || 0;
    if (!mailFlag(flag, unread, dt, { axes: "x" })) flag.rotation.x += ((unread ? 0 : -1.5) - flag.rotation.x) * 0.1;
    letter.visible = unread > 0;
    letter.position.y = 1.85 + Math.sin(t * 3) * 0.1;
    letter.rotation.y = t;
  });
  marker(this, mb, 0, 2.3, 0);
  this.addCircle(...xz(this.toWorld(room, 2.5, 0, 8.6)), 0.4);
  this.interact(room, { id: "mailbox", label: "check the mailbox (notifications)", local: [1.9, 0, 7.6], radius: 1.8, action: { type: "click", selector: "#notificationsBtn" } });
  const screen = makeScreen(1.8, 1.0, { placeholder: "welcome home ♡", border: "#ff8fb1" });
  const sign = new THREE.Group();
  sign.position.set(-2.7, 0, 8.6);
  sign.rotation.y = -0.4;
  g.add(sign);
  add(sign, box(0.12, 0.95, 0.12), wood, -0.7, 0.47, -0.005); // (centred under the board)
  add(sign, box(0.12, 0.95, 0.12), wood, 0.7, 0.47, -0.005);
  photoFrame(sign, 1.8, 1.0, 0, 1.5, 0);
  screen.mesh.position.set(0, 1.5, 0);
  sign.add(screen.mesh);
  const back = new THREE.Mesh(screen.mesh.geometry, screen.mesh.material);
  back.position.set(0, 1.5, -0.048); // (on the board's back, not floating behind it)
  back.rotation.y = Math.PI;
  sign.add(back);
  screen.draw({ title: "˗ˏˋ TOTO&DODO ˎˊ˗", lines: "forever and always ♡", center: true, foot: "open anything that sparkles ✦" });
  this.addCircle(...xz(this.toWorld(room, -2.7, 0, 8.6)), 0.3);
  // its still pieces merged (whatever moves, glows or is clicked stays as it is)
  bakeWhenSettled(room.group);
}
