// Fewer draw calls: once a place is built, its pieces that never move are merged
// into one mesh per material. It watches for a moment first, so anything an
// animation moves (or that's clickable, see-through, or marked live) stays as it was.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";

// is o, or anything between it and root, marked as something that moves later on?
function isLive(o, root) {
  for (let p = o; p && p !== root; p = p.parent) if (p.userData.live) return true;
  return false;
}

function snapshot(root) {
  root.updateMatrixWorld(true);
  const inv = root.matrixWorld.clone().invert();
  const out = new Map();
  root.traverse((o) => {
    if (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh) out.set(o, new THREE.Matrix4().multiplyMatrices(inv, o.matrixWorld));
  });
  return out;
}

export function bakeWhenSettled(root, wait = 1200) {
  if (root.userData.zoneSink) return; // (v2: a look its Blender zone replaces, zones/sink.js)
  const before = snapshot(root);
  setTimeout(() => {
    if (!root.parent) return; // gone already
    const after = snapshot(root);
    const groups = new Map();
    for (const [o, m0] of before) {
      const m1 = after.get(o);
      if (!m1 || !o.parent || !o.visible || !m0.equals(m1)) continue; // moved, or gone
      if (o.__noBake) continue; // (v2: a look its Blender zone takes over may leave any moment, zones/sink.js)
      const mat = o.material;
      // anything carrying its own data (clickable, a picture, a glow) is looked up later: leave it
      if (!mat || Array.isArray(mat) || mat.transparent || Object.keys(o.userData).length || isLive(o, root)) continue;
      if (m1.determinant() <= 0) continue; // mirrored pieces would turn inside out
      const geo = o.geometry;
      if (!geo?.attributes?.position || !geo.attributes.normal || geo.morphAttributes?.position) continue;
      const key = `${mat.uuid}|${Object.keys(geo.attributes).sort().join(",")}|${o.castShadow}|${o.receiveShadow}|${o.renderOrder}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push([o, m1]);
    }
    for (const list of groups.values()) {
      if (list.length < 2) continue;
      const geos = list.map(([o, m]) => (o.geometry.index ? o.geometry.toNonIndexed() : o.geometry.clone()).applyMatrix4(m));
      const merged = mergeGeometries(geos);
      for (const g of geos) g.dispose();
      if (!merged) continue;
      const first = list[0][0];
      const mesh = new THREE.Mesh(merged, first.material);
      mesh.castShadow = first.castShadow;
      mesh.receiveShadow = first.receiveShadow;
      mesh.renderOrder = first.renderOrder;
      root.add(mesh);
      for (const [o] of list) o.parent.remove(o);
    }
  }, wait);
}


// The whole island at once (for a phone, where every draw costs): after the world has been
// still for a moment, the pieces that never move are merged into one mesh per look and per
// patch of ground (so what's off screen is still skipped). Plain coloured pieces that differ
// only in colour share one mesh, their colours carried on the mesh itself. The pieces stay
// where they were, just not drawn: if one ever moves, hides or changes, its merge is undone
// on the spot (a new colour is simply painted in).
// A group that shows and hides as a whole (a building's insides, the christmas decorations)
// is marked __stop, and what's inside it is merged inside it.
const CELL = 16;
const _w = new THREE.Vector3();
const _m = new THREE.Matrix4();
// (a piece whose shape is changed in place counts as moved too)
const versions = (g) => {
  let v = g.index ? g.index.version : 0;
  for (const k in g.attributes) v += g.attributes[k].version;
  return v;
};

function bakeable(o) {
  if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh || !o.visible || o.__baked || o.__noBake) return false;
  if (o.layers.mask !== 1 || !o.frustumCulled || Object.keys(o.userData).length) return false;
  if (o.onBeforeRender !== THREE.Object3D.prototype.onBeforeRender) return false;
  const mat = o.material;
  if (!mat || Array.isArray(mat) || mat.transparent || mat.alphaTest > 0) return false;
  // (a shader that sways by the piece's own height would sway differently once merged)
  if (mat.onBeforeCompile !== THREE.Material.prototype.onBeforeCompile) return false;
  const geo = o.geometry;
  // (a single material draws the whole shape, whatever groups it's split into)
  if (!geo?.attributes?.position || !geo.attributes.normal || geo.morphAttributes?.position) return false;
  return true;
}

// can pieces with this material share a mesh with others of other colours?
function paintable(mat) {
  return (
    mat.type === "MeshStandardMaterial" && !mat.map && !mat.normalMap && !mat.emissiveMap && !mat.alphaMap && !mat.aoMap && !mat.envMap && !mat.roughnessMap && !mat.metalnessMap &&
    (mat.emissiveIntensity === 0 || mat.emissive.getHex() === 0)
  );
}
// everything about a plain material except its colour
const look = (m) =>
  [m.roughness, m.metalness, m.flatShading, m.side, m.fog, m.vertexColors, m.wireframe, m.depthTest, m.depthWrite, m.polygonOffset, m.polygonOffsetFactor, m.polygonOffsetUnits, m.toneMapped, m.envMapIntensity, m.visible, m.opacity].join();

// where a piece's merge lives: the nearest group marked __stop, or the top of the world
function stopOf(o, root) {
  let p = o.parent;
  while (p && p !== root && !p.__stop && p.parent !== root) p = p.parent;
  return p;
}
// is it still drawn from there (everything in between showing)?
function shownTo(o, stop) {
  for (let p = o.parent; p; p = p.parent) {
    if (p === stop) return true;
    if (!p.visible || p.userData.live) return false;
  }
  return false;
}

export function bakeScene(root, { wait = 1500, cell = CELL, onBaked = null } = {}) {
  const groups = [];
  const paints = new Map(); // shared vertex-colour materials, by look
  let timer = 0;
  let watch = 0;
  const unbake = (gr) => {
    if (!gr.mesh) return;
    gr.mesh.removeFromParent();
    gr.mesh.geometry.dispose();
    gr.mesh = null;
    for (const m of gr.members) {
      m.o.__baked = false;
      m.o.__noBake = true;
      m.o.layers.mask = m.mask;
    }
  };
  const rel = (o, stop) => _m.copy(stop.matrixWorld).invert().multiply(o.matrixWorld);
  const paintIn = (gr, m) => {
    const c = gr.mesh.geometry.attributes.color;
    const { r, g, b } = m.color;
    for (let i = m.from, j = 0; i < m.to; i++, j += 3) {
      if (m.base) c.setXYZ(i, m.base[j] * r, m.base[j + 1] * g, m.base[j + 2] * b);
      else c.setXYZ(i, r, g, b);
    }
  };
  // (each tick checks a tenth of the groups, round-robin: the whole set once a second as before,
  // never all in one frame; the stop's inverse once per group, a material's look once per tick)
  let cursor = 0;
  const _inv = new THREE.Matrix4();
  const _rel = new THREE.Matrix4();
  const looks = new Map();
  const check = () => {
    if (!groups.length) return;
    looks.clear();
    const n = Math.max(1, Math.ceil(groups.length / 10));
    for (let q = 0; q < n; q++) {
      const gr = groups[cursor++ % groups.length];
      if (!gr.mesh) continue;
      let repaint = false;
      _inv.copy(gr.stop.matrixWorld).invert();
      for (const m of gr.members) {
        const o = m.o;
        const mat = o.material;
        let lk = null;
        if (gr.paint) {
          lk = looks.get(mat);
          if (lk === undefined) looks.set(mat, (lk = look(mat)));
        }
        if (
          !o.visible || mat !== m.material || o.geometry !== m.geometry || o.layers.mask !== 0 || o.castShadow !== gr.mesh.castShadow ||
          versions(o.geometry) !== m.ver || !shownTo(o, gr.stop) || !_rel.multiplyMatrices(_inv, o.matrixWorld).equals(m.matrix) || (gr.paint && lk !== gr.look)
        ) {
          unbake(gr);
          break;
        }
        if (gr.paint && !mat.color.equals(m.color)) {
          m.color.copy(mat.color);
          paintIn(gr, m);
          repaint = true;
        }
      }
      if (repaint && gr.mesh) gr.mesh.geometry.attributes.color.needsUpdate = true;
    }
  };
  const run = (before) => {
    root.updateMatrixWorld(true);
    const byKey = new Map();
    for (const [o, m0] of before) {
      if (!o.parent || !bakeable(o)) continue;
      const stop = stopOf(o, root);
      if (!stop || stop !== m0.stop || !shownTo(o, stop)) continue;
      const m1 = rel(o, stop).clone();
      if (!m1.equals(m0.m) || m1.determinant() <= 0) continue;
      const mat = o.material;
      const geo = o.geometry;
      const paint = paintable(mat);
      const names = Object.keys(geo.attributes)
        .filter((k) => (paint ? k === "position" || k === "normal" || (k === "color" && mat.vertexColors) : true))
        .sort();
      const attrs = names.map((k) => `${k}${geo.attributes[k].itemSize}${geo.attributes[k].array.constructor.name}${geo.attributes[k].normalized ? "n" : ""}`).join(",");
      o.getWorldPosition(_w);
      const key = `${stop.uuid}|${paint ? `paint:${look(mat)}` : mat.uuid}|${paint ? "" : attrs}|${o.castShadow}|${o.receiveShadow}|${o.renderOrder}|${Math.floor(_w.x / cell)},${Math.floor(_w.z / cell)}`;
      if (!byKey.has(key)) byKey.set(key, { stop, paint, list: [] });
      byKey.get(key).list.push([o, m1, names]);
    }
    const spent = new Set();
    // a few at a time, with a breath between (merging everything at once held a phone
    // for a couple of seconds)
    const queue = [...byKey.values()].filter((g) => g.list.length >= 2);
    const step = () => {
      if (!root.parent && root.type !== "Scene") return;
      const t0 = performance.now();
      while (queue.length && performance.now() - t0 < 10) merge(queue.shift());
      if (queue.length) timer = setTimeout(step, 16);
      else finish();
    };
    const merge = ({ stop, paint, list }) => {
      if (!stop.parent && stop !== root) return;
      const members = [];
      let at = 0;
      const geos = list.map(([o, m1, names]) => {
        const src = o.geometry.index ? o.geometry.toNonIndexed() : o.geometry;
        const g = new THREE.BufferGeometry();
        for (const k of names) if (!paint || k !== "color") g.setAttribute(k, src.attributes[k].clone());
        g.applyMatrix4(m1);
        const n = g.attributes.position.count;
        const member = { o, mask: o.layers.mask, material: o.material, geometry: o.geometry, matrix: m1, ver: versions(o.geometry), from: at, to: at + n };
        if (paint) {
          member.color = o.material.color.clone();
          const vc = names.includes("color") ? src.attributes.color : null;
          member.base = vc ? new Float32Array(n * 3) : null;
          if (vc) for (let i = 0; i < n; i++) member.base.set([vc.getX(i), vc.getY(i), vc.getZ(i)], i * 3);
          const col = new Float32Array(n * 3);
          const { r, g: gg, b } = member.color;
          for (let i = 0; i < n; i++) {
            const k = i * 3;
            col[k] = (member.base ? member.base[k] : 1) * r;
            col[k + 1] = (member.base ? member.base[k + 1] : 1) * gg;
            col[k + 2] = (member.base ? member.base[k + 2] : 1) * b;
          }
          g.setAttribute("color", new THREE.BufferAttribute(col, 3));
        }
        if (src !== o.geometry) src.dispose();
        at += n;
        members.push(member);
        return g;
      });
      const merged = mergeGeometries(geos);
      for (const g of geos) g.dispose();
      if (!merged) return;
      const first = list[0][0];
      let material = first.material;
      const lk = paint ? look(first.material) : "";
      if (paint) {
        if (!paints.has(lk)) {
          const pm = first.material.clone();
          pm.color.set(0xffffff);
          pm.vertexColors = true;
          paints.set(lk, pm);
        }
        material = paints.get(lk);
      }
      const mesh = new THREE.Mesh(merged, material);
      mesh.castShadow = first.castShadow;
      mesh.receiveShadow = first.receiveShadow;
      mesh.renderOrder = first.renderOrder;
      mesh.matrixAutoUpdate = false;
      stop.add(mesh);
      mesh.updateMatrixWorld(true);
      for (const m of members) {
        m.o.__baked = true;
        m.o.layers.mask = 0;
        spent.add(m.o.geometry);
      }
      groups.push({ stop, mesh, members, paint, look: lk });
    };
    const finish = () => {
      // their own copies on the graphics card aren't needed now (anything still drawing one
      // just sends it again)
      for (const g of spent) g.dispose();
      watch = setInterval(check, 100);
      onBaked?.();
    };
    step();
  };
  const before = new Map();
  root.updateMatrixWorld(true);
  root.traverse((o) => {
    if (!o.isMesh) return;
    const stop = stopOf(o, root);
    if (stop) before.set(o, { stop, m: rel(o, stop).clone() });
  });
  timer = setTimeout(() => run(before), wait);
  return {
    get baked() {
      return groups.filter((g) => g.mesh).length;
    },
    dispose() {
      clearTimeout(timer);
      clearInterval(watch);
      for (const gr of groups) unbake(gr);
      groups.length = 0;
      for (const m of paints.values()) m.dispose();
      paints.clear();
    },
  };
}

// Everything that stands still stops working out where it is every frame (thousands of
// pieces: on a phone that was a third of each frame). Each one is still watched, cheaply,
// every frame: the moment one moves or turns it goes back to normal, before it is drawn.
// (E1: used on every device now. The watch keeps each piece's position, rotation and scale
// objects in their own lists, so the check reads the same kind of object every time, which is
// much quicker than going through each piece; onThaw is told when one starts moving again.)
export function freezeStill(root, { wait = 1500, onThaw = null } = {}) {
  let list = [];
  let P = [];
  let Q = [];
  let S = [];
  let parents = [];
  let snap = null;
  const take = (o) => [o.position.x, o.position.y, o.position.z, o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w, o.scale.x, o.scale.y, o.scale.z];
  const before = new Map();
  root.traverse((o) => {
    // (the scene itself too: while it works itself out, it makes everything else do so)
    if (o.matrixAutoUpdate) before.set(o, take(o));
  });
  // (frozen: the list's pieces, their transform parts and parents, and a snapshot to check against)
  const freeze = (keep) => {
    const at = list.length;
    for (const [o] of keep) {
      list.push(o);
      P.push(o.position);
      Q.push(o.quaternion);
      S.push(o.scale);
      parents.push(o.parent);
    }
    const next = new Float64Array(list.length * 10);
    if (snap) next.set(snap.subarray(0, at * 10));
    snap = next;
    keep.forEach(([o, b], i) => {
      snap.set(b, (at + i) * 10);
      o.updateMatrix();
      o.matrixAutoUpdate = false;
    });
  };
  const settle = (seen, top) => {
    const keep = [];
    for (const [o, a] of seen) {
      if (!o.matrixAutoUpdate || (!o.parent && o !== top)) continue;
      const b = take(o);
      if (a.some((v, i) => v !== b[i])) continue;
      keep.push([o, b]);
    }
    freeze(keep);
    seen.clear();
  };
  const later = [];
  const timer = setTimeout(() => settle(before, root), wait);
  return {
    get frozen() {
      return list.length;
    },
    // something streamed in after the start (a zone, a room): watched for a moment the same way,
    // then whatever stood still stops working out where it is every frame
    add(sub) {
      const seen = new Map();
      sub.traverse((o) => o.matrixAutoUpdate && seen.set(o, take(o)));
      later.push(setTimeout(() => settle(seen, sub), wait));
    },
    // before each frame is drawn
    tick() {
      if (!snap) return;
      for (let i = list.length - 1; i >= 0; i--) {
        const k = i * 10;
        const p = P[i];
        const q = Q[i];
        const s = S[i];
        if (
          p.x === snap[k] && p.y === snap[k + 1] && p.z === snap[k + 2] && q._x === snap[k + 3] && q._y === snap[k + 4] && q._z === snap[k + 5] && q._w === snap[k + 6] &&
          s.x === snap[k + 7] && s.y === snap[k + 8] && s.z === snap[k + 9] && list[i].parent === parents[i]
        )
          continue;
        const o = list[i];
        o.matrixAutoUpdate = true;
        o.matrixWorldNeedsUpdate = true;
        onThaw?.(o);
        // (swap the last one in)
        const j = list.length - 1;
        list[i] = list[j];
        P[i] = P[j];
        Q[i] = Q[j];
        S[i] = S[j];
        parents[i] = parents[j];
        snap.copyWithin(k, j * 10, j * 10 + 10);
        list.pop();
        P.pop();
        Q.pop();
        S.pop();
        parents.pop();
      }
    },
    dispose() {
      clearTimeout(timer);
      for (const t of later) clearTimeout(t);
      for (const o of list) o.matrixAutoUpdate = true;
      list = [];
      P = Q = S = parents = [];
      snap = null;
    },
  };
}
