// The Blender zones in the game (pilot P3/P4, VISUAL-TECH-SPEC §N): loads the zone GLBs (meshopt +
// WebP, fetched at runtime, never bundled or precached), binds their materials to the game's
// shared runtime materials and atlases, turns every repeated kind into one InstancedMesh culled
// per instance, switches the LOD alternates, and hands the ANIM_/SOCK_/SCREEN_ nodes to the zone
// wiring (v2-gate.js, v2-plaza.js, v2-paths.js). Visuals only: colliders, seats, interactables,
// anchors and slots stay the code constants the World registered (REBUILD-PLAN 6.1).
// Called by island.js only when zones/mode.js says v2. (A static import: a separate lazy chunk
// moved esbuild's shared helpers into a new chunk the 2D app loads, which the 2D smoke rejects.)
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { glow, windify, setGlowHalo } from "../world.js";
import { libraryMaterial, nearFade } from "../render/libmat.js";
import * as gateZone from "./v2-gate.js";
import * as plazaZone from "./v2-plaza.js";
import * as pathsZone from "./v2-paths.js";
import { localZones, wireLocal } from "./v2-local.js";
import { sinkNow, releaseSink } from "./sink.js";
import { shellFiles, shellFarFiles, wireShell, wireShellFar } from "./v2-shell.js";
import { setAnimalLib, tickAnimals, animalStats, resetAnimals } from "./animals.js";
import { setCharacterKit, tickCharacters, characterStats, resetCharacters, npcZoneIn } from "./characters.js";
import { setClipsFromGLTF, resetClips, CARRIERS } from "../anim/clips.js";
import { wireSeasonal } from "./v2-seasonal.js";

// what each tier loads: the meadow layers follow the device (assets-w1b: phone 1, tablet 1+2, computer 1+2+3)
function meadowLayers(tier, isTouch) {
  if (tier === "low") return [1];
  if (tier === "mid") return isTouch && Math.min(screen.width, screen.height) < 700 ? [1] : [1, 2];
  return [1, 2, 3];
}

// per-kind distances (assets-w1b runtime request 8): [match, { max, fade, cast, lite }]
const KINDS = [
  [/grass/, { max: 34, fade: [26, 34] }],
  [/speckle/, { max: 30, fade: [22, 30] }],
  // (the old-style three-blade tufts: from above they read as the legacy dark stars on the lawn,
  // the user's report 2026-11-16; the painted grass cards cover the lawn now, so they are not drawn)
  [/tuft/, { max: -1 }],
  [/petal/, { max: 40 }],
  [/pebble/, { max: 55 }],
  [/stones/, { max: 60 }],
  [/flower|bloom|clump/, { max: 55 }],
  [/rock/, { max: 90, cast: true, lite: 45 }],
  [/tree|pine|wild_/, { max: 400, cast: true, lite: 45 }],
  [/lamppost/, { max: 400, cast: true }],
];
const kindRule = (k) => (KINDS.find(([re]) => re.test(k)) || [null, { max: 80 }])[1];
const CELL = 16;

// ---- materials -------------------------------------------------------------------------------
function makeMaterials({ world, base, small, onPalette, renderer = null, msaa = true }) {
  // the leaf and grass cards cut out by coverage only where there is MSAA to cover with; without it
  // alphaToCoverage leaves the card's square panel drawn solid (the phones' "flat smeared leaves")
  // (leaf cards and crowns fade from 2.6 m in: a follow camera near a crown sees through it)
  const LEAF_FADE = [0.9, 2.6];
  const loader = new THREE.TextureLoader();
  const texs = new Map();
  // every texture is a promise kept (review-threejs assets 6): the sets wait for theirs before they
  // show (mats.ready), a failed one is said in the console, and each is uploaded once it is in, so
  // the first frame that shows it neither draws three's black stand-in nor stalls on the upload
  const ready = [];
  // (phones: 2x, review-threejs performance 22; it is paid on every ground fragment)
  const aniso = Math.min(small ? 2 : 8, renderer?.capabilities?.getMaxAnisotropy?.() || 4);
  const tex = (file, { srgb = true, repeat = false } = {}) => {
    if (texs.has(file)) return texs.get(file);
    const t = new THREE.Texture();
    t.flipY = false; // glTF UVs
    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.wrapS = t.wrapT = repeat ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
    t.anisotropy = !srgb ? 1 : repeat ? aniso : Math.min(4, aniso);
    ready.push(
      loader
        .loadAsync(base + "tex/" + file)
        .then((l) => {
          t.image = l.image;
          t.needsUpdate = true;
          try {
            renderer?.initTexture(t);
          } catch {}
        })
        .catch((e) => console.warn("zone texture", file, e)),
    );
    texs.set(file, t);
    return t;
  };
  const size = small ? 512 : 1024;
  const mats = new Map();
  const once = (key, make) => {
    if (!mats.has(key)) mats.set(key, make());
    return mats.get(key);
  };
  // the painted kit atlases (assets/materials/tdd_kit_bind.js, ported): map x tint mask
  const kitTints = new Map();
  const kit = (kitName, variant, extras) =>
    once(`kit|${kitName}|${variant}`, () => {
      const m = new THREE.MeshStandardMaterial({ name: `MAT_kit_${kitName}`, map: tex(`T_${kitName}_${size}.webp`), roughness: variant === "gloss" ? 0.3 : 0.86, metalness: 0, flatShading: false });
      if (variant === "clip") {
        m.alphaTest = 0.45;
        m.alphaToCoverage = msaa;
        m.side = THREE.DoubleSide;
      }
      if (extras?.tdd_kit_mask) {
        const mask = tex(`${extras.tdd_kit_mask}_${size / 2}.webp`, { srgb: false });
        let roles = {};
        try {
          roles = JSON.parse(extras.tdd_tint || "{}");
        } catch {}
        if (!kitTints.has(kitName)) kitTints.set(kitName, [0, 1, 2].map(() => new THREE.Color(1, 1, 1)));
        const tints = kitTints.get(kitName);
        // (the only tinted region so far is the gate bench cushion: the legacy cushion pink)
        if (roles.r === "user") tints[0].set("#f7b8cf");
        m.onBeforeCompile = (sh) => {
          sh.uniforms.tddKitMask = { value: mask };
          sh.uniforms.tddKitTint = { value: tints };
          sh.fragmentShader = sh.fragmentShader
            .replace("#include <common>", "#include <common>\nuniform sampler2D tddKitMask;\nuniform vec3 tddKitTint[3];")
            .replace(
              "#include <map_fragment>",
              "#include <map_fragment>\n{ vec3 km = texture2D(tddKitMask, vMapUv).rgb;\n  diffuseColor.rgb *= mix(vec3(1.0), tddKitTint[0], km.r) * mix(vec3(1.0), tddKitTint[1], km.g) * mix(vec3(1.0), tddKitTint[2], km.b); }",
            );
        };
        m.customProgramCacheKey = () => "tdd_kit";
        // (the animals tint per node: their own instances of this material, zones/animals.js)
        m.userData.kitMask = mask;
      }
      return m;
    });
  // a vertex-coloured variant of one of the world's theme materials: same Color object, so
  // applyPalette's colour change reaches it with no extra work
  const follow = (key, src, extra = {}) =>
    once(key, () => {
      const m = new THREE.MeshStandardMaterial({ name: key, vertexColors: true, flatShading: src.flatShading, roughness: src.roughness, metalness: 0, ...extra });
      m.color = src.color;
      return m;
    });
  const fadePatch = (near, far) => `
      {
        vec3 io = (modelMatrix * vec4(instanceMatrix[3].xyz, 1.0)).xyz;
        transformed *= 1.0 - smoothstep(${near.toFixed(1)}, ${far.toFixed(1)}, distance(io, cameraPosition));
        // (seen from high above, upright cards are only their dark edges: X marks over the lawn,
        // the user's report; they fold away as the view turns steeply down)
        transformed *= 1.0 - smoothstep(0.9, 0.97, abs(normalize(cameraPosition - io).y));
      }`;
  function material(src, mesh) {
    const n = (src.name || "").replace(/\.\d+$/, "");
    const x = src.userData || {};
    const geo = mesh.geometry;
    const kitM = /^MAT_kit_([a-z0-9_]+?)(?:_(clip|gloss))?$/.exec(n);
    if (kitM) return kit(x.tdd_kit || kitM[1], x.tdd_variant || kitM[2] || "opaque", x);
    switch (n) {
      case "MAT_glow_warm":
        return glow.warm;
      case "MAT_glow_pink":
        return glow.pink;
      case "MAT_glow_magic":
        return glow.magic;
      // the draw-call pass joins the three glows into one vertex-coloured material: each vertex's
      // colour says its kind (warm / pink / magic, the glow.* base colours), whose live emissive it
      // takes, so warm keeps the night ramp (assets/blender/_scripts/README.md, "Draw-call pass")
      case "MAT_glow_vc":
        return once(n, () => {
          const m = new THREE.MeshStandardMaterial({ name: n, vertexColors: true, flatShading: true, roughness: glow.warm.roughness, metalness: 0 });
          m.userData.isGlow = true;
          const e = (g) => {
            const c = new THREE.Color();
            return { get value() { return c.copy(g.emissive).multiplyScalar(g.emissiveIntensity); } };
          };
          m.onBeforeCompile = (sh) => {
            sh.uniforms.gW = e(glow.warm);
            sh.uniforms.gP = e(glow.pink);
            sh.uniforms.gM = e(glow.magic);
            sh.fragmentShader =
              "uniform vec3 gW, gP, gM;\n" +
              sh.fragmentShader.replace(
                "#include <emissivemap_fragment>",
                "#include <emissivemap_fragment>\n{ vec3 c = vColor.rgb; vec3 kw = vec3(1.0, 0.791, 0.434), kp = vec3(1.0, 0.631, 0.761), km = vec3(0.686, 0.578, 1.0);\n" +
                  "  float dw = distance(c, kw), dp = distance(c, kp), dm = distance(c, km);\n" +
                  "  totalEmissiveRadiance = dw < dp && dw < dm ? gW : (dp < dm ? gP : gM); }",
              );
          };
          m.customProgramCacheKey = () => "tdd_glow_vc";
          return m;
        });
      case "MAT_tuft":
        return world.tuftMat;
      // the shell (Wave 5): its lawn, islet grass and trees and the cloud sea are the theme's own
      case "MAT_grass":
        return world.grassMat;
      case "MAT_canopy":
        return world.canopyMat;
      case "MAT_pine":
        return world.pineMat;
      case "MAT_cloud":
        return world.cloudMat;
      case "MAT_shell_far_terrain":
        return once(n, () => new THREE.MeshStandardMaterial({ name: n, vertexColors: true, flatShading: true, roughness: 0.95, metalness: 0, fog: false, side: THREE.DoubleSide }));
      case "MAT_far_water":
        return once(n, () => {
          const t = tex(`T_island_water_${small ? 256 : 512}.webp`, { repeat: true });
          const m = new THREE.MeshStandardMaterial({ name: n, map: t, emissive: "#ffffff", emissiveMap: t, emissiveIntensity: 0.3, roughness: 0.3, metalness: 0, fog: false, side: THREE.DoubleSide });
          m.userData.scroll = t;
          return m;
        });
      case "MAT_veg_vc":
        return once(n, () => new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.88, metalness: 0 }));
      // (crowns and leaf cards dissolve right by the camera: nearFade)
      case "MAT_veg_canopy_vc":
        return nearFade(follow(n, world.canopyMat), ...LEAF_FADE);
      case "MAT_veg_pine_vc":
        return nearFade(follow(n, world.pineMat), ...LEAF_FADE);
      case "MAT_veg_tuft_vc":
        return once(n, () => windify(follow(n + "|base", world.tuftMat), 0.09, 0.35));
      // wave 1d leaf / blossom cards: T_veg_leaves x vertex paint, cut out, both sides; canopy and pine
      // cards take the theme's colour like the crowns they hang on, the wild kinds keep their own
      case "MAT_veg_canopy_clip":
      case "MAT_veg_pine_clip":
      case "MAT_veg_leaf_clip":
        return once(n, () => {
          const src = n === "MAT_veg_canopy_clip" ? world.canopyMat : n === "MAT_veg_pine_clip" ? world.pineMat : null;
          const m = new THREE.MeshStandardMaterial({ name: n, vertexColors: true, map: tex(`T_veg_leaves_${small ? 256 : 512}.png`), alphaTest: 0.45, alphaToCoverage: msaa, side: THREE.DoubleSide, roughness: 0.88, metalness: 0, flatShading: false });
          if (src) m.color = src.color;
          return nearFade(m, ...LEAF_FADE);
        });
      case "MAT_veg_grass_clip": {
        // (two card heights, two sway weights: assets-w1b grass a 0.44, b 0.53)
        const h = /grass_b/.test(mesh.userData.tddKind || "") ? 0.53 : 0.44;
        return once(`${n}|${h}`, () => {
          const m = new THREE.MeshStandardMaterial({ name: n, vertexColors: true, map: tex(`T_veg_grass_${small ? 256 : 512}.png`), alphaTest: 0.5, alphaToCoverage: msaa, side: THREE.DoubleSide, roughness: 0.9, metalness: 0, flatShading: false });
          // (the theme's tuft colour, lifted: the painted cards are dark at the root and read brown
          // against the lawn at mid distance, assets-w1b weakness 1)
          // (2026-11-16, the user: from above the cards read as dark star-shaped tufts on the lawn:
          // they now take the lawn's own colour, a touch of the tuft green, lifted, so they melt in)
          const lift = () => m.color.copy(world.grassMat.color).lerp(world.tuftMat.color, 0.3).multiplyScalar(1.25);
          lift();
          onPalette(lift);
          return windify(m, 0.11, h, fadePatch(26, 34));
        });
      }
      case "MAT_veg_ground_vc":
        return once(n, () => {
          const m = new THREE.MeshStandardMaterial({ name: n, vertexColors: true, map: world.grassMat.map, roughness: world.grassMat.roughness, metalness: 0, flatShading: false });
          // (no forward depth offset: the lawn under it is pushed back instead; pulled forward it beat
          // every floor and deck lying on the lawn at a low view, the bakery's floor among them)
          m.color = world.grassMat.color;
          // the weather's own ground (snow, autumn grass) follows the lawn
          onPalette(() => {
            if (m.map !== world.grassMat.map) {
              m.map = world.grassMat.map;
              m.needsUpdate = true;
            }
          });
          return m;
        });
      // the shared palette atlas (race, coaster raw parts): they drew white with nothing bound
      case "MAT_atlas_palette":
      case "MAT_vc_palette":
        return once(n, () => libraryMaterial(new THREE.MeshStandardMaterial({ name: n, map: tex(`T_tdd_palette_${size}.webp`), roughness: 0.88, metalness: 0, flatShading: false, vertexColors: n === "MAT_vc_palette" }), geo));
      case "MAT_paths_pool":
        return once(n, () => new THREE.MeshBasicMaterial({ map: tex("T_paths_pool_64.png"), transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0 }));
      case "MAT_vc_foliage":
        return once(n, () => nearFade(libraryMaterial(new THREE.MeshStandardMaterial({ name: n, map: tex(`T_tdd_foliage_${size}.webp`), roughness: 0.9, metalness: 0, flatShading: false }), geo)));
      case "MAT_willow_bark":
        return once(n, () => libraryMaterial(new THREE.MeshStandardMaterial({ name: n, map: tex(`T_willow_bark_${size}.webp`, { repeat: true }), roughness: 0.92, metalness: 0, flatShading: false }), geo));
      default:
        // (runtime materials a legacy builder registered: lake water, the bakery's paper, floor,
        // neon and glass, the garden's water; else the SCREEN_ faces and anything unknown)
        return world.zoneMats?.[n] || null;
    }
  }
  const speckle = (m) =>
    once("speckle|" + m.uuid, () => {
      const c = m.clone();
      return windify(c, 0.06, 0.3, fadePatch(22, 30));
    });
  return {
    tex,
    ready: () => Promise.allSettled(ready.slice()),
    material,
    speckle,
    kitTints,
    kitMat: (kitName, v = "opaque") => mats.get(`kit|${kitName}|${v}`),
    farWater: () => mats.get("MAT_far_water"),
    dispose() {
      for (const t of texs.values()) t.dispose();
      for (const m of mats.values()) if (m !== world.tuftMat) m.dispose();
    },
  };
}

// ---- repeated kinds: one InstancedMesh per kind, refilled by frustum and distance --------------
class Repeats {
  constructor(root) {
    this.root = root;
    this.kinds = new Map(); // key -> kind
    this.frustum = new THREE.Frustum();
    this._pm = new THREE.Matrix4();
    this._s = new THREE.Sphere();
    this._at = new THREE.Vector3(1e9, 0, 0);
    this._q = new THREE.Quaternion();
    this.timer = 0;
    this.drawn = 0;
  }
  // matrices (world) of one more holder of a kind
  add(kindName, geometry, material, matrices, colors = null, lite = null) {
    const key = kindName + "|" + geometry.uuid + "|" + material.uuid;
    let k = this.kinds.get(key);
    if (!k) {
      k = { name: kindName, geometry, material, rule: kindRule(kindName), list: [], cols: [], lite };
      this.kinds.set(key, k);
    }
    for (const m of matrices) k.list.push(m);
    if (colors) k.cols.push(...colors);
    else if (k.cols.length) for (let i = 0; i < matrices.length; i++) k.cols.push(null);
    if (lite && !k.lite) k.lite = lite;
  }
  // the kinds added since the last build get their meshes (under parent; streamed ones wait in a
  // detached group until their shaders are compiled, then move to the zone root)
  build(parent = this.root) {
    const tmpP = new THREE.Vector3();
    const tmpQ = new THREE.Quaternion();
    const tmpS = new THREE.Vector3();
    const made = [];
    for (const k of this.kinds.values()) {
      if (k.mesh) continue;
      const n = k.list.length;
      if (!k.geometry.boundingSphere) k.geometry.computeBoundingSphere();
      const bs = k.geometry.boundingSphere;
      k.mats = new Float32Array(n * 16);
      k.sph = new Float32Array(n * 4);
      k.list.forEach((m, i) => {
        m.toArray(k.mats, i * 16);
        m.decompose(tmpP, tmpQ, tmpS);
        const c = bs.center.clone().applyMatrix4(m);
        k.sph[i * 4] = c.x;
        k.sph[i * 4 + 1] = c.y;
        k.sph[i * 4 + 2] = c.z;
        k.sph[i * 4 + 3] = bs.radius * Math.max(tmpS.x, tmpS.y, tmpS.z);
      });
      // cells, so most of the island is skipped with one test
      const cells = new Map();
      for (let i = 0; i < n; i++) {
        const cx = Math.floor(k.sph[i * 4] / CELL);
        const cz = Math.floor(k.sph[i * 4 + 2] / CELL);
        const ck = cx * 4096 + cz;
        if (!cells.has(ck)) cells.set(ck, { x: (cx + 0.5) * CELL, z: (cz + 0.5) * CELL, y: 0, r: 0, idx: [] });
        cells.get(ck).idx.push(i);
      }
      k.cells = [...cells.values()].map((c) => {
        let y0 = Infinity, y1 = -Infinity, rr = 0;
        for (const i of c.idx) {
          y0 = Math.min(y0, k.sph[i * 4 + 1]);
          y1 = Math.max(y1, k.sph[i * 4 + 1]);
          rr = Math.max(rr, k.sph[i * 4 + 3]);
        }
        c.y = (y0 + y1) / 2;
        c.r = Math.hypot(CELL / 2, CELL / 2, (y1 - y0) / 2) + rr;
        c.idx = Int32Array.from(c.idx);
        return c;
      });
      const mk = (geo, mat) => {
        const im = new THREE.InstancedMesh(geo, mat, n);
        im.frustumCulled = false; // (culled here, per instance)
        im.count = 0;
        im.castShadow = Boolean(k.rule.cast);
        im.receiveShadow = true;
        im.matrixAutoUpdate = false;
        im.__noBake = true;
        // (rewritten as you move: a dynamic buffer; and a bounding sphere over the whole island, so
        // taps and shots test the instances themselves, review-threejs lighting 7; the cards that
        // never block anything, grass and flowers, are kept out of ray picking altogether)
        im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        if (k.rule.cast) im.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 0, 0), 500);
        else im.raycast = () => {};
        im.userData.zoneKind = k.name;
        if (k.cols.length && k.cols.some(Boolean)) {
          im.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(n * 3).fill(1), 3);
          im.instanceColor.setUsage(THREE.DynamicDrawUsage);
          k.colArr = new Float32Array(n * 3).fill(1);
          k.cols.forEach((c, i) => c && c.toArray(k.colArr, i * 3));
        }
        parent.add(im);
        made.push(im);
        return im;
      };
      k.mesh = mk(k.geometry, k.material);
      if (k.lite && k.rule.lite) {
        k.far = mk(k.lite.geometry, k.lite.material);
        k.far.castShadow = false; // (only ever past the shadow box)
      }
      k.list = null;
      k.cols = null;
    }
    return made;
  }
  // camera: the main view; force: refill now
  update(dt, camera, force = false) {
    this.timer -= dt;
    camera.getWorldQuaternion(this._q);
    // (a refill after 1 m or a 3 degree turn: the 4 m margin below keeps the edges filled meanwhile;
    // every 0.4 m it was every frame while driving, the phone's main cost on the scooter)
    const moved = camera.position.distanceToSquared(this._at) > 1 || (this._lastQ && 1 - Math.abs(this._q.dot(this._lastQ)) > 3.4e-4);
    if (!force && !moved && this.timer > 0) return;
    this.timer = 0.25;
    this._at.copy(camera.position);
    this._lastQ = (this._lastQ || new THREE.Quaternion()).copy(this._q);
    this._pm.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    this.frustum.setFromProjectionMatrix(this._pm);
    const cx = camera.position.x, cy = camera.position.y, cz = camera.position.z;
    const s = this._s;
    const MARGIN = 4;
    let drawn = 0;
    let castChanged = false;
    for (const k of this.kinds.values()) {
      if (k.pending) continue;
      const max = k.rule.max;
      const liteAt = k.far ? k.rule.lite : Infinity;
      const useFrustum = !k.rule.cast;
      if (!useFrustum && !force && k.at && (k.at.x - cx) ** 2 + (k.at.y - cy) ** 2 + (k.at.z - cz) ** 2 < 4) {
        drawn += (k.mesh.count > 0 ? 1 : 0) + (k.far?.count > 0 ? 1 : 0);
        continue;
      }
      if (!useFrustum) (k.at ||= new THREE.Vector3()).set(cx, cy, cz);
      const A = k.mesh.instanceMatrix.array;
      const B = k.far ? k.far.instanceMatrix.array : null;
      const CA = k.mesh.instanceColor?.array;
      const CB = k.far?.instanceColor?.array;
      let na = 0, nb = 0;
      for (const c of k.cells) {
        const dc = Math.hypot(c.x - cx, c.y - cy, c.z - cz) - c.r;
        if (dc > max) continue;
        if (useFrustum) {
          s.center.set(c.x, c.y, c.z);
          s.radius = c.r + MARGIN;
          if (!this.frustum.intersectsSphere(s)) continue;
        }
        const idx = c.idx;
        for (let j = 0; j < idx.length; j++) {
          const i = idx[j];
          const o = i * 4;
          const d = Math.hypot(k.sph[o] - cx, k.sph[o + 1] - cy, k.sph[o + 2] - cz);
          if (d - k.sph[o + 3] > max) continue;
          if (useFrustum) {
            s.center.set(k.sph[o], k.sph[o + 1], k.sph[o + 2]);
            s.radius = k.sph[o + 3] + MARGIN;
            if (!this.frustum.intersectsSphere(s)) continue;
          }
          if (d > liteAt) {
            for (let e = 0; e < 16; e++) B[nb * 16 + e] = k.mats[i * 16 + e];
            if (CB) for (let e = 0; e < 3; e++) CB[nb * 3 + e] = k.colArr[i * 3 + e];
            nb++;
          } else {
            for (let e = 0; e < 16; e++) A[na * 16 + e] = k.mats[i * 16 + e];
            if (CA) for (let e = 0; e < 3; e++) CA[na * 3 + e] = k.colArr[i * 3 + e];
            na++;
          }
        }
      }
      // (a casting kind whose near set changed: the cached shadows must be drawn again, review lighting 10)
      if (k.rule.cast && k.mesh.count !== na) castChanged = true;
      drawn += this.commit(k.mesh, na) + this.commit(k.far, nb);
    }
    this.drawn = drawn;
    if (castChanged) this.onCastChange?.();
  }
  commit(m, n) {
    if (!m) return 0;
    m.count = n;
    m.visible = n > 0;
    if (!n) return 0;
    m.instanceMatrix.clearUpdateRanges();
    m.instanceMatrix.addUpdateRange(0, n * 16);
    m.instanceMatrix.needsUpdate = true;
    if (m.instanceColor) {
      m.instanceColor.clearUpdateRanges();
      m.instanceColor.addUpdateRange(0, n * 3);
      m.instanceColor.needsUpdate = true;
    }
    return 1;
  }
  get instances() {
    let n = 0;
    for (const k of this.kinds.values()) n += k.mats.length / 16;
    return n;
  }
  dispose() {
    for (const k of this.kinds.values()) for (const m of [k.mesh, k.far]) m?.dispose();
  }
}

// the animals kit's assets the game uses ([name, has a _far rest mesh]): lite and far come with them
const ANIMALS = [
  ["ani_pet_cat", 0], ["ani_pet_bunny", 0], ["ani_pet_hats", 0], ["ani_deer", 0],
  ["ani_cow_holstein", 1], ["ani_cow_brown", 1], ["ani_goat_white", 1], ["ani_goat_brown", 1], ["ani_sheep", 1],
  ["ani_hen", 1], ["ani_rooster", 1], ["ani_chick", 1],
  ["ani_duck_hen", 1], ["ani_duck_drake", 1], ["ani_duckling", 1],
  ["ani_hedgehog", 0], ["ani_bee", 0], ["ani_butterfly", 0], ["ani_dookie", 0],
];

// ---- LOD alternates (SM_..._LOD1 / _LOD2 siblings in the zone GLB) ---------------------------------
const LOD_AT = [32, 70];

// ---- loading ------------------------------------------------------------------------------------
export async function loadZones({ world, willow, scene, camera, renderer, tier, isTouch, base, kit, onCard, haze = null }) {
  const small = tier === "low" || tier === "mid";
  const loader = new GLTFLoader();
  // (no decoder workers: the decoder builds them from its own source text, which a minified build
  // renames, so they never answer and the island never loads; review-threejs assets 13 is declined)
  loader.setMeshoptDecoder(MeshoptDecoder);
  const paletteHooks = [];
  world.paletteHooks.push((p) => paletteHooks.forEach((fn) => fn(p)));
  const msaa = Boolean(renderer?.getContextAttributes?.()?.antialias) || tier === "high" || tier === "ultra";
  const mats = makeMaterials({ world, base, small, renderer, msaa, onPalette: (fn) => paletteHooks.push(fn) });
  // the lawn is pushed back in depth: every floor, deck, path and paint lying on it at the same height
  // wins, instead of the lawn showing through them in stripes as you move (the user's flicker and
  // "flooring clipping into the ground", 2026-11-16)
  world.grassMat.polygonOffset = true;
  world.grassMat.polygonOffsetFactor = 2;
  world.grassMat.polygonOffsetUnits = 4;
  world.grassMat.needsUpdate = true;
  // (one read of the pack's record per visit)
  const packInfo = fetch(base + "pack-info.json")
    .then((r) => (r.ok ? r.json() : null))
    .catch(() => null);
  let gone = false;
  const root = new THREE.Group();
  root.name = "zones";
  const repeats = new Repeats(root);
  const lods = [];
  const anims = []; // (t, dt, camPos) per zone
  const stats = { files: {}, bytes: 0, meshes: 0, instances: 0, kinds: 0, lods: 0, anchors: null };

  const get = async (file, dir = "zones/") => {
    let last = null;
    for (let tryN = 0; tryN < 3; tryN++) {
      // (a file that STALLS, 25 s with nothing arriving, is given up on and asked for again; a slow
      // link that keeps delivering is never cut off, review-threejs assets 4; a 4xx is final)
      const ac = new AbortController();
      let timer = setTimeout(() => ac.abort(), 25000);
      try {
        const res = await fetch(base + dir + file, { signal: ac.signal });
        if (!res.ok) {
          const err = new Error(`${file}: HTTP ${res.status}`);
          if (res.status >= 400 && res.status < 500) err.final = true;
          throw err;
        }
        let buf;
        if (res.body?.getReader) {
          const reader = res.body.getReader();
          const chunks = [];
          let n = 0;
          for (;;) {
            clearTimeout(timer);
            timer = setTimeout(() => ac.abort(), 25000);
            const { done, value } = await reader.read();
            if (done) break;
            chunks.push(value);
            n += value.byteLength;
          }
          const u8 = new Uint8Array(n);
          let at = 0;
          for (const c of chunks) {
            u8.set(c, at);
            at += c.byteLength;
          }
          buf = u8.buffer;
        } else buf = await res.arrayBuffer();
        clearTimeout(timer);
        // (a 200 that holds an HTML fallback page is not a GLB: no point asking again)
        const head = new Uint8Array(buf, 0, Math.min(4, buf.byteLength));
        if (head[0] !== 0x67 || head[1] !== 0x6c || head[2] !== 0x54 || head[3] !== 0x46) {
          const err = new Error(`${file}: not a GLB`);
          err.final = true;
          throw err;
        }
        stats.files[file] = buf.byteLength;
        stats.bytes += buf.byteLength;
        // (a decode that never answers fails the file after 60 s instead of holding the loading
        // card: the island then opens without that zone, with the "didn't load" card)
        let parseTimer = 0;
        try {
          return await Promise.race([
            loader.parseAsync(buf, base + dir),
            new Promise((_, rej) => {
              parseTimer = setTimeout(() => rej(Object.assign(new Error(`${file}: decode timed out`), { final: true })), 60000);
            }),
          ]);
        } finally {
          clearTimeout(parseTimer);
        }
      } catch (e) {
        clearTimeout(timer);
        last = e;
        if (e?.final) break;
        await new Promise((r) => setTimeout(r, 400 * (tryN + 1)));
      }
    }
    throw last;
  };

  // the zone files this device loads, all at once (they come down in parallel)
  // what the first frame needs (where you arrive and what you see from there: about 3 MB);
  // the island-wide scatter and the meadow stream in right after it (streamRest)
  const want = {
    gate: "zon_gate.glb",
    plaza: "zon_plaza.glb",
    paths: "zon_paths.glb",
    pathsRaw: "zon_paths_raw.glb",
    strandA: "veg_willow_strand_a.glb",
    strandB: "veg_willow_strand_b.glb",
  };
  // the island shell (lawn, cliffs, crystals, islets): seen from everywhere, so in the first frame
  shellFiles(small).forEach((f, i) => (want["shell" + i] = f));
  const later = {
    // (phones load the lite scatter as their only set: 0.81 MB less and about a quarter less leaf-card
    // fill, Wave 1d; computers draw the full set near and the lite one past 45 m)
    scatter: small ? "zon_scatter_lite_raw.glb" : "zon_scatter_raw.glb",
    scatterLite: small ? null : "zon_scatter_lite_raw.glb",
  };
  for (const l of meadowLayers(tier, isTouch)) later["meadow" + l] = `zon_scatter_meadow${l}_raw.glb`;
  const fetchSet = async (set) => {
    const names = Object.keys(set).filter((k) => set[k]);
    const got = await Promise.all(names.map((k) => get(set[k])));
    return Object.fromEntries(names.map((k, i) => [k, got[i].scene]));
  };
  const G = await fetchSet(want);
  // the painted Blender lawn (T_ground_lawn_<size>, when the pack carries it): it becomes the lawn's
  // own texture, so the shell lawn, the islets and the ground paint all wear it; the weather's
  // ground (snow, autumn) still takes over and gives it back (world.applyPalette uses grassTex)
  // (its maker's binding: sRGB albedo, repeating about 24 times over the lawn, 512 on phones; it
  // carries its own hue, so the theme's lawn tint is drawn most of the way to neutral; the weather's
  // ground, snow or autumn, keeps its own texture and tint)
  packInfo
    .then(async (info) => {
      const f = `T_ground_lawn_${small ? 512 : 1024}.webp`;
      if (gone || !info?.files?.["tex/" + f] || !world.grassTex) return;
      const t = mats.tex(f, { repeat: true });
      await mats.ready();
      if (gone || !t.image) return;
      t.flipY = world.grassTex.flipY;
      t.repeat.set(24, 24);
      world.grassTex = t;
      world.lawnPainted = true;
      stats.lawn = f;
      const white = new THREE.Color(1, 1, 1);
      paletteHooks.push((p) => {
        if (!p.ground) world.grassMat.color.set(p.grassTint || "#ffffff").lerp(white, 0.7);
      });
      if (world.palette) world.applyPalette(world.palette);
    })
    .catch((e) => console.warn("zone lawn:", e));
  // the animals kit comes down now, behind the first-frame set (streamAnimals wears it)
  const animalT0 = performance.now();
  const animalFetch = (async () => {
    const info = await packInfo;
    if (info?.leftOut?.some((p) => p.startsWith("animals/"))) return { leftOut: true };
    const has = (n) => !info?.files || `animals/${n}.glb` in info.files;
    const names = [];
    for (const [n, far] of ANIMALS) {
      const lite = has(n + "_lite");
      if (!small || !lite) names.push(n);
      if (lite) names.push(n + "_lite");
      if (far && has(n + "_far")) names.push(n + "_far");
    }
    const before = stats.bytes;
    try {
      const got = await Promise.all(names.map((n) => get(n + ".glb", "animals/")));
      return { names, got, bytes: stats.bytes - before };
    } catch (e) {
      return { error: String(e).slice(0, 120) };
    }
  })();
  stats.firstFrameBytes = stats.bytes;

  // the characters kit (Wave 10): the look rules' data now, each GLB the first time a look wears it
  // (a worn look is about 0.5 MB; the avatars and NPCs keep their procedural look until then)
  const chrT0 = performance.now();
  let chrCache = null;
  (async () => {
    const info = await packInfo;
    if (gone || info?.leftOut?.some((p) => p.startsWith("characters/"))) return void (stats.characters = { leftOut: true });
    if (info?.files && !("characters/avatar_rig.json" in info.files)) return void (stats.characters = { missing: true });
    const rig = await fetch(base + "characters/avatar_rig.json").then((r) => (r.ok ? r.json() : null));
    if (!rig || gone) return;
    const kitBase = mats.material({ name: "MAT_kit_avatar", userData: { tdd_kit: "avatar", tdd_variant: "opaque", tdd_kit_mask: "T_avatar_mask", tdd_tint: '{"b": "user", "g": "paint", "r": "fur"}' } }, { geometry: null });
    for (let k = 0; k < 200 && !gone && !(kitBase.map?.image && kitBase.userData.kitMask?.image); k++) await new Promise((r) => setTimeout(r, 50));
    if (gone) return;
    const cache = new Map();
    const load = (name) => {
      if (!cache.has(name))
        cache.set(
          name,
          get(name + ".glb", "characters/").then((gl) => {
            const sc = gl.scene;
            sc.traverse((o) => {
              if (!o.isMesh) return;
              o.material.map?.dispose();
              o.material.dispose();
              o.material = kitBase;
            });
            sc.updateMatrixWorld(true);
            return sc;
          }),
        );
      return cache.get(name);
    };
    chrCache = cache;
    setCharacterKit({ load, rig, base: kitBase }, world);
    // the avatar's clips (anim/): every avatar binds them the first frame they are in
    if (!info?.files || "characters/chr_avatar_clips.glb" in info.files)
      get("chr_avatar_clips.glb", "characters/")
        .then((g) => !gone && setClipsFromGLTF(g, "chr_avatar_clips"))
        .catch((e) => console.warn("avatar clips", e));
    stats.characters = { ms: Math.round(performance.now() - chrT0), get now() { return { files: cache.size, ...characterStats() }; } };
  })().catch((e) => (stats.characters = { error: String(e).slice(0, 120) }));

  // the leftovers (rebuild/reports/assets-leftovers.md): the far pines (full on high / ultra, the lite
  // impostor on low / mid), the boundary fence, the clouds (one InstancedMesh per variant, following the
  // legacy instances) and the Blender glow halo for every glow sprite; their legacy looks stop drawing
  stats.leftovers = {};
  (async () => {
    const info = await packInfo;
    const has = (f) => !info?.files || f in info.files;
    const fine = tier === "high" || tier === "ultra";
    const one = async (n) => {
      if (gone || !has(`env/${n}.glb`)) return null;
      const gl = await get(n + ".glb", "env/");
      let mesh = null;
      gl.scene.updateMatrixWorld(true);
      gl.scene.traverse((o) => {
        if (!mesh && o.isMesh) mesh = o;
      });
      if (!mesh || gone) return null;
      return { geo: mesh.geometry.clone().applyMatrix4(mesh.matrixWorld), mat: mats.material(mesh.material, mesh) };
    };
    if (has("tex/T_glow_halo_64.png"))
      new THREE.ImageLoader().load(base + "tex/T_glow_halo_64.png", (img) => {
        if (gone) return;
        setGlowHalo(img);
        stats.leftovers.halo = true;
      });
    const pines = world.scenePines;
    const pine = pines && (await one(fine ? "env_farpine" : "env_farpine_lite"));
    if (pine) {
      const m = pine.mat.clone();
      m.fog = pines.material.fog;
      pines.geometry.dispose();
      pines.geometry = pine.geo;
      pines.material = m;
      pines.computeBoundingSphere();
      stats.leftovers.pines = fine ? "full" : "lite";
    }
    const F = world.fence;
    for (const part of ["post", "rope"]) {
      const a = F?.[part] && (await one(`env_fence_${part}${small ? "_lite" : ""}`));
      if (!a) continue;
      F[part].geometry.dispose();
      F[part].geometry = a.geo;
      F[part].material = a.mat;
      F[part].computeBoundingSphere();
      stats.leftovers.fence = true;
    }
    const C = world.clouds;
    const vars = C ? await Promise.all(["a", "b", "c"].map((v) => one(`env_cloud_${v}${small ? "_lite" : ""}`))) : [];
    if (C && vars.every(Boolean) && !gone) {
      // (the theme's colour, glow and opacity stay cloudMat's; the kit atlas paints them)
      world.cloudMat.map = vars[0].mat.map;
      world.cloudMat.needsUpdate = true;
      const n = C.count;
      const sets = vars.map((v, k) => {
        const im = new THREE.InstancedMesh(v.geo, world.cloudMat, Math.ceil((n - k) / 3));
        im.frustumCulled = false;
        im.name = `env_cloud_${"abc"[k]}`;
        C.parent.add(im);
        return im;
      });
      C.visible = false;
      world.onClouds = () => {
        const src = C.instanceMatrix.array;
        for (let i = 0; i < n; i++) sets[i % 3].instanceMatrix.array.set(src.subarray(i * 16, i * 16 + 16), ((i / 3) | 0) * 16);
        for (const s of sets) s.instanceMatrix.needsUpdate = true;
      };
      world.onClouds();
      stats.leftovers.clouds = small ? "lite" : "full";
    }
  })().catch((e) => (stats.leftovers.error = String(e).slice(0, 120)));

  // the seasonal zones (Wave 11): each one the first time its theme shows (v2-seasonal.js)
  const seasons = {};
  stats.seasonal = {};
  const loadSeason = async (theme) => {
    seasons[theme] = "loading";
    const file = `zon_seasonal_${theme}.glb`;
    const info = await packInfo;
    if (gone || info?.leftOut?.includes("zones/" + file) || (info?.files && !(("zones/" + file) in info.files))) return void (stats.seasonal[theme] = { leftOut: true });
    const t0 = performance.now();
    const gl = await get(file);
    if (gone) return;
    const sc = gl.scene;
    sc.traverse((o) => {
      if (!o.isMesh) return;
      const b = mats.material(o.material, o);
      if (b && b !== o.material) {
        o.material.map?.dispose();
        o.material.dispose();
      }
      if (b) o.material = b;
      const glowy = o.material.emissiveIntensity > 0 && o.material.emissive?.getHex() > 0;
      o.castShadow = !glowy && !o.material.transparent;
      o.receiveShadow = true;
    });
    await mats.ready();
    if (gone) return;
    seasons[theme] = sc;
    wireSeasonal(theme, { world, scene: sc, anims, stats: stats.seasonal });
    stats.seasonal[theme] = { ...stats.seasonal[theme], ms: Math.round(performance.now() - t0) };
  };
  paletteHooks.push((p) => {
    for (const theme of ["christmas", "halloween"]) if (p[theme] && !seasons[theme]) loadSeason(theme).catch((e) => (stats.seasonal[theme] = { error: String(e).slice(0, 120) }));
  });

  // the lite holders by name: the far version of each repeated kind (same holders, _lite sources)
  const liteBy = new Map();
  const readLite = (sc) =>
    sc?.traverse((o) => {
      if (!o.isInstancedMesh) return;
      const h = holderOf(o);
      if (h) liteBy.set(h.userData.name + "|" + (o.parent.isGroup && o.parent !== h ? o.parent.children.indexOf(o) : 0), o);
    });

  function holderOf(o) {
    for (let p = o; p; p = p.parent) if (/^GI_/.test(p.userData?.name || "")) return p;
    return null;
  }
  const kindOf = (name) => name.replace(/^GI_/, "").replace(/_x[m\d]+_z[m\d]+(_s\d+)?$/, "");

  // the meadow's ground paint lies 4 mm above the lawn and ran on under the houses, so inside a house
  // it drew over the floor (the user's "room floors gone", 2026-11-17): its triangles inside a house go
  const houses = [...world.rooms.values()].filter((r) => /^(pavilion|tower|hall|bakery)$/.test(r.def.kind) && r.radius).map((r) => [r.group.position.x, r.group.position.z, r.radius]);
  const _c = new THREE.Vector3();
  function cutRoomFloors(o) {
    const g = o.geometry;
    const P = g.attributes.position;
    if (!P || !houses.length) return;
    const idx = g.index ? g.index.array : null;
    const n = idx ? idx.length : P.count;
    const keep = [];
    const at = (i) => (idx ? idx[i] : i);
    for (let i = 0; i < n; i += 3) {
      _c.set(0, 0, 0);
      for (let j = 0; j < 3; j++) _c.x += P.getX(at(i + j)) / 3, _c.z += P.getZ(at(i + j)) / 3;
      _c.applyMatrix4(o.matrixWorld);
      if (!houses.some(([x, z, r]) => (x - _c.x) ** 2 + (z - _c.z) ** 2 < r * r)) keep.push(at(i), at(i + 1), at(i + 2));
    }
    if (keep.length < n) g.setIndex(keep);
  }
  // bind, sort and collect one zone scene
  const nodes = {};
  function take(zone, sc, { skipRepeats = null, parent = root } = {}) {
    sc.updateMatrixWorld(true);
    const byName = new Map();
    const giMeshes = [];
    sc.traverse((o) => {
      const nm = o.userData?.name || o.name;
      if (nm) byName.set(nm, o);
      if (!o.isMesh) return;
      const h = holderOf(o);
      if (h) {
        o.userData.tddKind = kindOf(h.userData.name);
        giMeshes.push([o, h]);
      }
      const list = Array.isArray(o.material) ? o.material : [o.material];
      const bound = list.map((m) => {
        const b = mats.material(m, o);
        if (b && b !== m) {
          m.map?.dispose();
          m.dispose();
        }
        return b || m;
      });
      o.material = Array.isArray(o.material) ? bound : bound[0];
      const mm = Array.isArray(o.material) ? o.material[0] : o.material;
      if (mm.name === "MAT_veg_ground_vc") cutRoomFloors(o);
      const isGlow = mm === glow.warm || mm === glow.pink || mm === glow.magic || mm.userData?.isGlow === true;
      const name = o.userData?.name || "";
      o.castShadow = !isGlow && mm !== world.tuftMat && !/^SCREEN_/.test(name) && !mm.transparent && !(mm.alphaTest > 0 && /grass|ground/.test(mm.name)) && !mm.polygonOffset && mm.name !== "MAT_veg_ground_vc";
      o.receiveShadow = true;
      o.__noBake = true;
      if (mm.name === "MAT_paths_pool" || mm.blending === THREE.AdditiveBlending) {
        o.userData.nightOnly = 0.55;
        o.renderOrder = 1;
        o.castShadow = false;
      }
      if (mm.polygonOffset) o.renderOrder = -1; // (the ground paint: drawn before the lawn under it)
      stats.meshes++;
    });
    // repeats out of the scene, into their kinds
    for (const [o, h] of giMeshes) {
      if (skipRepeats?.(o, h)) continue;
      const kind = o.userData.tddKind;
      const mats4 = [];
      let cols = null;
      if (o.isInstancedMesh) {
        const m = new THREE.Matrix4();
        for (let i = 0; i < o.count; i++) {
          o.getMatrixAt(i, m);
          mats4.push(m.clone().premultiply(o.matrixWorld));
        }
        if (o.instanceColor) {
          cols = [];
          for (let i = 0; i < o.count; i++) {
            const c = new THREE.Color();
            o.getColorAt(i, c);
            cols.push(c);
          }
        }
      } else mats4.push(o.matrixWorld.clone());
      let material = Array.isArray(o.material) ? o.material[0] : o.material;
      if (/speckle/.test(kind)) material = mats.speckle(material);
      const li = liteBy.get(h.userData.name + "|" + (o.parent.isGroup && o.parent !== h ? o.parent.children.indexOf(o) : 0));
      const lite = zone === "scatter" && li && li.geometry !== o.geometry ? { geometry: li.geometry, material: mats.material(li.material, li) || li.material } : null;
      repeats.add(kind, o.geometry, material, mats4, cols, lite);
      o.removeFromParent();
    }
    // LOD alternates
    const lodSets = new Map();
    sc.traverse((o) => {
      const nm = o.userData?.name || "";
      const m = /^(.*)_LOD([12])$/.exec(nm);
      if (m) {
        if (!lodSets.has(m[1])) lodSets.set(m[1], [byName.get(m[1]) || null, null, null]);
        lodSets.get(m[1])[+m[2]] = o;
      }
    });
    for (const [, set] of lodSets) {
      if (!set[0]) continue;
      const p = new THREE.Vector3();
      set[0].getWorldPosition(p);
      set[1] && (set[1].visible = false);
      set[2] && (set[2].visible = false);
      lods.push({ set, p, cur: 0 });
    }
    nodes[zone] = byName;
    parent.add(sc);
    return byName;
  }

  take("gate", G.gate);
  take("plaza", G.plaza, { skipRepeats: (o) => /firefly/.test(o.userData.tddKind) });
  take("paths", G.paths);
  take("pathsRaw", G.pathsRaw);
  const shellN = new Map();
  shellFiles(small).forEach((f, i) => {
    // (the crystals spin: their own InstancedMesh, v2-shell.js)
    for (const [k, v] of take("shell" + i, G["shell" + i], { skipRepeats: (o) => /crystal/.test(o.userData.tddKind) })) shellN.set(k, v);
  });
  repeats.build();
  stats.instances = repeats.instances;
  stats.kinds = repeats.kinds.size;
  stats.lods = lods.length;
  // the strand sources: their own materials bound the same way
  // (each card hangs from its origin: the node's own offset goes into the geometry)
  const strandOf = (sc) => {
    let mesh = null;
    sc.updateMatrixWorld(true);
    sc.traverse((o) => o.isMesh && !mesh && (mesh = o));
    return mesh && { geometry: mesh.geometry.clone().applyMatrix4(mesh.matrixWorld) };
  };
  const strands = { a: strandOf(G.strandA), b: strandOf(G.strandB) };
  strands.map = mats.tex(`T_tdd_foliage_${small ? 512 : 1024}.webp`);

  // the zones' wiring: their moving parts, screens, lamps' halos
  const ctx = { THREE, world, willow, scene, camera, kit, root, nodes, mats, anims, strands, stats, glow, onPalette: (fn) => paletteHooks.push(fn) };
  wireShell({ world, N: shellN, anims, root, mats, onPalette: ctx.onPalette });
  gateZone.wire(ctx);
  plazaZone.wire(ctx);
  pathsZone.wire(ctx);
  // whatever the zones keep still stops working out where it is every frame
  root.traverse((o) => {
    if (o.userData.zoneLive) return;
    o.updateMatrix();
  });
  world.root.add(root);
  if (world.palette) world.applyPalette(world.palette);
  root.updateMatrixWorld(true);
  repeats.update(0, camera, true);

  const camPos = new THREE.Vector3();
  let lodTimer = 0;
  // phones: a diary ring house far off is not drawn at all (its legacy look left with it), so the
  // ring's ~200 draws only count where you are
  const ringZones = [];
  // (the lite zones' own cull_m, assets/specs/diaryring/zon_diaryring_<id>_lite.json)
  const RING_CULL = small ? 60 : Infinity;
  // (the first-frame atlases are in and uploaded before the island shows)
  await mats.ready();
  // the tree crowns (every repeated kind drawn with leaf cards or a crown material): spheres a
  // little smaller than each instance's bounds, in 8 m cells, for the follow camera's arm
  let crownGrid = null;
  let crownKinds = -1;
  const CROWN = /^MAT_veg_(canopy|pine|leaf)_(clip|vc)$|^MAT_vc_foliage$/;
  const crowns = () => {
    if (crownGrid && crownKinds === repeats.kinds.size) return crownGrid;
    crownKinds = repeats.kinds.size;
    crownGrid = new Map();
    for (const k of repeats.kinds.values()) {
      const mn = k.mesh?.material?.name || "";
      if (!CROWN.test(mn) || !k.sph) continue;
      for (let i = 0; i < k.sph.length; i += 4) {
        // (the card mesh's bounds are generous: the solid core is about 0.7 of them)
        const y = k.sph[i + 1], r = k.sph[i + 3] * 0.7;
        if (y < 1.6 || r < 0.6) continue; // (bushes and low shrubs: the camera stays above them)
        const key = Math.floor(k.sph[i] / 8) + "," + Math.floor(k.sph[i + 2] / 8);
        if (!crownGrid.has(key)) crownGrid.set(key, []);
        crownGrid.get(key).push(k.sph[i], y, k.sph[i + 2], r);
      }
    }
    return crownGrid;
  };
  // how far along from -> to (0..1) the segment first enters a crown
  const crownBlock = (from, to) => {
    const g = crowns();
    if (!g.size) return 1;
    const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
    const a = dx * dx + dy * dy + dz * dz;
    if (a < 1e-6) return 1;
    let best = 1;
    const x0 = Math.floor(Math.min(from.x, to.x) / 8 - 1), x1 = Math.floor(Math.max(from.x, to.x) / 8 + 1);
    const z0 = Math.floor(Math.min(from.z, to.z) / 8 - 1), z1 = Math.floor(Math.max(from.z, to.z) / 8 + 1);
    for (let cx = x0; cx <= x1; cx++)
      for (let cz = z0; cz <= z1; cz++) {
        const L = g.get(cx + "," + cz);
        if (!L) continue;
        for (let i = 0; i < L.length; i += 4) {
          const ox = from.x - L[i], oy = from.y - L[i + 1], oz = from.z - L[i + 2], r = L[i + 3];
          const c = ox * ox + oy * oy + oz * oz - r * r;
          if (c <= 0) continue; // (the player stands inside this crown's sphere: never block on it)
          const b = 2 * (ox * dx + oy * dy + oz * dz);
          const disc = b * b - 4 * a * c;
          if (disc < 0) continue;
          const t = (-b - Math.sqrt(disc)) / (2 * a);
          if (t > 0 && t < best) best = t;
        }
      }
    return best;
  };
  return {
    root,
    stats,
    repeats,
    crownBlock,
    // after the first frame: the scatter and the meadow, compiled (compile: the island's own shader
    // warm-up for the picture's render target) while still detached, then shown in one go
    async streamRest(compile) {
      const t0 = performance.now();
      const farSet = Object.fromEntries(shellFarFiles(small).map((f, i) => ["far" + i, f]));
      const [L, F, pinesY] = await Promise.all([
        fetchSet(later),
        fetchSet(farSet),
        fetch(base + `zones/far_pines${small ? "_lite" : ""}_y.json`)
          .then((r) => (r.ok ? r.json() : null))
          .catch(() => null),
      ]);
      if (gone) return;
      const farN = new Map();
      readLite(L.scatterLite);
      const pending = new THREE.Group();
      take("scatter", L.scatter, { parent: pending });
      for (const l of meadowLayers(tier, isTouch)) take("meadow" + l, L["meadow" + l], { parent: pending });
      Object.keys(farSet).forEach((k) => {
        for (const [n, v] of take(k, F[k], { parent: pending })) farN.set(n, v);
      });
      const made = repeats.build(pending);
      for (const k of repeats.kinds.values()) if (made.includes(k.mesh)) k.pending = true;
      for (const m of made) {
        m.count = 1;
        m.visible = true;
      }
      pending.updateMatrixWorld(true);
      // (the far shell's haze patch goes on before its shaders are compiled, not after, when both
      // compiled again on the frame they first showed: review-threejs assets 10)
      if (haze) {
        const seen = new Set();
        const hg = new THREE.Group();
        for (const [, o] of farN) {
          if (!o.isMesh || seen.has(o.material)) continue;
          seen.add(o.material);
          hg.add(new THREE.Mesh(o.geometry, o.material));
        }
        haze(hg);
      }
      try {
        await mats.ready();
        await compile(pending);
      } catch {}
      if (gone) return;
      for (const m of made) {
        m.count = 0;
        m.visible = false;
      }
      const added = [...pending.children];
      for (const c of added) root.add(c);
      root.updateMatrixWorld(true);
      for (const c of added) world.onStreamIn?.(c);
      wireShellFar({ world, N: farN, anims, tier, haze: null, farPinesY: pinesY });
      for (const k of repeats.kinds.values()) k.pending = false;
      repeats.update(0, camera, true);
      stats.instances = repeats.instances;
      stats.kinds = repeats.kinds.size;
      stats.streamedMs = Math.round(performance.now() - t0);
    },
    update(dt, t) {
      camera.getWorldPosition(camPos);
      repeats.update(dt, camera);
      lodTimer -= dt;
      if (lodTimer <= 0) {
        lodTimer = 0.3;
        for (const r of ringZones) {
          // (a room's inside shows exactly when the legacy one would: world.update's room.inner rule)
          const on = r.inner ? r.inner.visible : Math.hypot(r.at.x - camPos.x, r.at.z - camPos.z) < RING_CULL;
          if (on !== r.on) {
            r.on = on;
            for (const o of r.roots) o.visible = on;
          }
        }
        for (const l of lods) {
          const d = l.p.distanceTo(camPos);
          const want = d < LOD_AT[0] ? 0 : d < LOD_AT[1] || !l.set[2] ? 1 : 2;
          const w = l.set[want] ? want : 0;
          if (w === l.cur) continue;
          l.set.forEach((o, i) => o && (o.visible = i === w));
          l.cur = w;
        }
      }
      for (const fn of anims) fn(t, dt, camPos);
      tickAnimals(dt, camPos);
      tickCharacters(camPos);
      const fw = mats.farWater();
      if (fw) fw.userData.scroll.offset.y -= dt * 0.55; // (the falls run downhill, as legacy)
    },
    // then the places further out, nearest first (to wherever you are by then), one at a time;
    // each one's legacy look leaves only once its zone is in (zones/sink.js)
    async streamLocal(compile, where, crossfade = null) {
      // (places the pack left out, inconsistent assets: they keep their legacy look, no request)
      let left = [];
      let present = null;
      try {
        const info = await packInfo;
        left = (info?.leftOut || []).map((p) => p.replace(/^zones\//, ""));
        if (info?.files) present = new Set(Object.keys(info.files).map((p) => p.replace(/^zones\//, "")));
      } catch {}
      // (a zone's optional file the pack did not carry is simply not asked for)
      const all = localZones(world, small).map((z) => (present ? { ...z, files: z.files.filter((f, i) => i === 0 || present.has(f)) } : z));
      // (phones load the diary ring as _lite zones: v2-local.js)
      // (the rooms' insides stay computers only; the ring's places come as _lite zones on phones)
      const todo = all.filter((z) => !z.files.some((f) => left.includes(f)) && !(z.room && small));
      stats.local = {};
      for (const z of all) if (!todo.includes(z)) {
        stats.local[z.id] = { leftOut: true };
        releaseSink(world, z.id);
      }
      // (a zone's gameplay constants the collider JSON cannot carry: games ballOnly, trail pads)
      const consts = {};
      const one = async (z) => {
        const t0 = performance.now();
        try {
          const before = stats.bytes;
          const cf = `zon_${z.id}.constants.json`;
          if (present?.has(cf)) consts[z.id] = await fetch(base + "zones/" + cf).then((r) => (r.ok ? r.json() : null)).catch(() => null);
          const scenes = await Promise.all(z.files.map((f) => get(f)));
          if (gone) return;
          const pending = new THREE.Group();
          const N = new Map();
          scenes.forEach((g, i) => {
            for (const [k, v] of take(`${z.id}${i}`, g.scene, { parent: pending })) N.set(k, v);
          });
          const made = repeats.build(pending);
          const mine = [...repeats.kinds.values()].filter((k) => made.includes(k.mesh));
          for (const k of mine) k.pending = true;
          for (const m of made) {
            m.count = 1;
            m.visible = true;
          }
          pending.updateMatrixWorld(true);
          try {
            await mats.ready();
        await compile(pending);
          } catch {}
          if (gone) return;
          for (const m of made) {
            m.count = 0;
            m.visible = false;
          }
          // (in view and near: the old look fades out over the new one instead of popping)
          camera.getWorldPosition(camPos);
          if (crossfade && z.at.distanceTo(camPos) < 90) await crossfade();
          if (gone) return;
          const faces = sinkNow(world, z.id);
          if (z.ring) ringZones.push({ at: z.at, roots: [...pending.children], on: true, inner: z.room ? world.rooms.get(z.room)?.inner || null : null });
          const added = [...pending.children];
          for (const c of added) root.add(c);
          root.updateMatrixWorld(true);
          for (const c of added) world.onStreamIn?.(c);
          wireLocal(z.id, { world, N, faces, anims, mats, root, renderer, scenes: scenes.map((g) => g.scene), files: z.files, consts: consts[z.id] || null });
          // (the garden's and farm's own NPC copies give way to the characters kit's: characters.js)
          if (z.id === "garden" || z.id === "farm") npcZoneIn(world, z.id, scenes.map((g) => g.scene));
          for (const k of mine) k.pending = false;
          repeats.update(0, camera, true);
          if (world.palette) world.applyPalette(world.palette);
          stats.local[z.id] = { ms: Math.round(performance.now() - t0), bytes: stats.bytes - before };
        } catch (e) {
          // (the legacy look simply stays, merged as it would have been)
          stats.local[z.id] = { error: String(e).slice(0, 120) };
          releaseSink(world, z.id);
        }
      };
      // two at a time, nearest first (to wherever you are by then): one slow file holds up only itself
      // (a zone with a `near` distance, a room's inside, waits until you are that close to it)
      const worker = async () => {
        while (todo.length && !gone) {
          const at = where();
          todo.sort((a, b) => a.at.distanceToSquared(at) - b.at.distanceToSquared(at));
          const k = todo.findIndex((z) => !z.near || Math.hypot(z.at.x - at.x, z.at.z - at.z) < z.near);
          if (k < 0) {
            await new Promise((r) => setTimeout(r, 700));
            continue;
          }
          await one(todo.splice(k, 1)[0]);
        }
      };
      await Promise.all([worker(), worker()]);
      stats.instances = repeats.instances;
    },
    // the animals kit (Wave 9): every creature, farm animal, duck and garden critter built so far
    // swaps its procedural look for its rig (zones/animals.js); phones load the _lite rigs only
    async streamAnimals(crossfade = null) {
      const t0 = animalT0;
      // (fetched since the first-frame set came in, while the island furnished and compiled behind
      // the loading screen: by the first frame the rigs are usually here, so nobody sees the swap)
      const r = await animalFetch;
      if (r.leftOut) return (stats.animals = { leftOut: true });
      if (r.error) return (stats.animals = { error: r.error });
      const { names, got, bytes } = r;
      if (gone) return;
      const scenes = new Map();
      let roles = null;
      names.forEach((n, i) => {
        const sc = got[i].scene;
        sc.traverse((o) => {
          if (!o.isMesh) return;
          const x = o.material?.userData || {};
          if (!roles && x.tdd_tint) {
            try {
              roles = JSON.parse(x.tdd_tint);
            } catch {}
          }
          const b = mats.material(o.material, o);
          if (b && b !== o.material) o.material.dispose();
          if (b) o.material = b;
          o.castShadow = false;
          o.receiveShadow = true;
          o.geometry.userData.kit = true; // (shared by every rig cloned from it: never disposed with one)
        });
        scenes.set(n, sc);
      });
      // (the painted atlas and the tint mask are in before anything wears them: never a black frame)
      const km = mats.kitMat("animals");
      for (let k = 0; k < 160 && km && !(km.map?.image && km.userData.kitMask?.image); k++) await new Promise((r) => setTimeout(r, 50));
      if (crossfade) await crossfade();
      if (gone) return;
      setAnimalLib({ scenes, small, roles: roles || { r: "fur", g: "paint", b: "user" } });
      // the cat's clips (anim/): every cat binds them the first frame they are in
      // then every other carrier (scale.md), one after another so no long task lands on a phone
      packInfo.then(async (info) => {
        for (const [dir, n] of CARRIERS) {
          if (gone) return;
          if (info?.files && !(dir + n + ".glb" in info.files)) continue;
          try {
            const g = await get(n + ".glb", dir);
            if (!gone) setClipsFromGLTF(g, n);
          } catch (e) {
            console.warn("clips", n, e);
          }
          await new Promise((r) => setTimeout(r, 0));
        }
      });
      stats.animals = { ms: Math.round(performance.now() - t0), msAfterFirstFrame: Math.round(performance.now() - (world.firstFrameAt ?? performance.now())), bytes, files: names.length, ...animalStats() };
    },
    dispose() {
      gone = true;
      // (the animals kit belongs to this visit: a second visit loads its own)
      resetAnimals();
      resetCharacters();
      resetClips();
      for (const sc of chrCache?.values() || []) sc.then((s) => s.traverse((o) => o.geometry?.dispose())).catch(() => {});
      for (const sc of Object.values(seasons)) {
        if (!sc?.isObject3D) continue;
        sc.removeFromParent();
        sc.traverse((o) => o.geometry?.dispose());
      }
      repeats.dispose();
      root.traverse((o) => {
        if (o.isMesh) o.geometry?.dispose();
      });
      mats.dispose();
      root.removeFromParent();
      void onCard;
      void renderer;
      void scene;
    },
  };
}
