// The local zones (Waves 3 and 4): which files each one is, where it stands (for streaming by
// proximity), and the little wiring each needs once it is in. Their gameplay, runtime pieces and
// legacy builders are untouched (zones/sink.js says what of the legacy look leaves).
import * as THREE from "three";

export function localZones(world, small) {
  const room = (id) => world.rooms.get(id)?.group.position;
  return [
    { id: "bakery", files: ["zon_bakery.glb", "zon_bakery_raw.glb"], at: room("bakery") },
    { id: "stall", files: ["zon_bakery_stall.glb"], at: room("stall") },
    { id: "garden", files: small ? ["zon_garden_lite.glb", "zon_garden_lite_raw.glb"] : ["zon_garden.glb", "zon_garden_raw.glb"], at: room("garden") },
    { id: "farm", files: ["zon_farm.glb", "zon_farm_raw.glb"], at: room("farm") },
    { id: "lake", files: ["zon_lake.glb", "zon_lake_raw.glb"], at: room("lake") },
    { id: "chill", files: ["zon_lake_chill.glb", "zon_lake_chill_raw.glb"], at: room("chill") },
    { id: "swings", files: ["zon_lake_swings.glb", "zon_lake_swings_raw.glb"], at: room("swings") },
    { id: "picnic", files: ["zon_lake_picnic.glb"], at: world.picnic?.position },
    // Wave 7 games: the sky trail out past the fence, and the games (pitch, moles, signs)
    { id: "trail", files: ["zon_trail.glb", "zon_trail_raw.glb"], at: world.zoneAt?.trail },
    { id: "games", files: ["zon_games.glb", "zon_games_raw.glb"], at: world.zoneAt?.games },
    // Wave 7 rides: the coaster (its train stays coaster.js's) and the race road round the island
    { id: "coaster", files: small ? ["zon_coaster_lite.glb", "zon_coaster_lite_raw.glb"] : ["zon_coaster.glb", "zon_coaster_raw.glb"], at: world.coasterSpot },
    { id: "race", files: small ? ["zon_race_lite.glb", "zon_race_lite_raw.glb"] : ["zon_race.glb", "zon_race_raw.glb"], at: new THREE.Vector3(0, 0, 79.6) },
    // Wave 6: the balloon station, the cinema, the lookout (its crowns and roof are their own zones,
    // hidden as you climb / stand on top, as legacy)
    { id: "balloon", files: ["zon_balloon.glb", "zon_balloon_raw.glb"], at: room("balloon") },
    { id: "cinema", files: ["zon_cinema.glb", "zon_cinema_raw.glb"], at: room("cinema") },
    { id: "lookout", files: ["zon_lookout.glb", small ? "zon_lookout_leaves_lite.glb" : "zon_lookout_leaves.glb", small ? "zon_lookout_leaves_lite_raw.glb" : "zon_lookout_leaves_raw.glb", "zon_lookout_roof.glb"], at: room("lookout") },
    // the diary ring (Wave 2a): the 9 houses and 3 outdoor places; their insides stay legacy
    // (and, since the leftovers pass, the heart place and the photo wall)
    ...["song", "note", "photos", "calendar", "poems", "gift", "wardrobe", "art", "diary", "weather", "wishlist", "discord", "heart", "pinboard"].map((id) => ({
      id: `dr_${id}`,
      // (phones: the place's one _lite zone, pass 2; same colliders, sockets and interactables)
      files: small ? [`zon_diaryring_${id}_lite.glb`] : [`zon_diaryring_${id}.glb`, `zon_diaryring_${id}_raw.glb`],
      at: room(id),
      ring: true,
    })),
    // the rooms' insides (Wave 8): each one streams in once you are within 55 m of it (the legacy
    // furnish distance), so a door never shows an empty room; computers only, like the ring
    ...["diary", "song", "note", "photos", "calendar", "poems", "gift", "wardrobe", "art", "bakery"].map((id) => ({
      id: `rm_${id}`,
      files: [`zon_room_${id}.glb`, `zon_room_${id}_raw.glb`],
      at: room(id),
      ring: true,
      near: 55,
      room: id,
    })),
    // (phones draw the ring's _lite zones, each hidden beyond its cull_m, 60 m: zones/runtime.js)
  ].filter((z) => z.at);
}

// nodes the legacy runtime still draws itself (its own animals, plants, fire, swinging seats):
// the zone's copies of them stay hidden
const HIDE = {
  coaster: /^(INST_|HIT_)/,
  // (the moving pad, star, ring, moles, dummies and flags are the legacy pieces, kept)
  trail: /^(ANIM_|INST_|HIT_)/,
  // (the moles and straw dummies are the zone's, riding the legacy groups: bindGames)
  games: /^(ANIM_(?!act_games_(mole|dummy))|INST_|HIT_)/,
  race: /^(INST_|HIT_)/,
  // (Wave 6: what moves, blinks or is tapped stays the legacy piece, zones/sink.js motion test)
  balloon: /^(ANIM_|INST_|HIT_)/,
  cinema: /^(ANIM_|INST_|HIT_)/,
  lookout: /^(ANIM_|INST_|HIT_)/,
  // (the diary ring: every moving part is the legacy piece, which stays: zones/sink.js motion)
  ...Object.fromEntries(["song", "note", "photos", "calendar", "poems", "gift", "wardrobe", "art", "diary", "weather", "wishlist", "discord", "heart", "pinboard"].map((id) => [`dr_${id}`, /^(ANIM_|INST_|HIT_)/])),
  // (the rooms: what moves, is tapped or shows live content is the legacy piece; the zone's
  // SCREEN_ planes stay hidden, the legacy screens are drawn and tapped where they stand)
  // (the bakery's chalk menu is no tap target: its zone plane shows the legacy canvas, as the signs do)
  ...Object.fromEntries(["diary", "song", "note", "photos", "calendar", "poems", "gift", "wardrobe", "art", "bakery"].map((id) => [`rm_${id}`, id === "bakery" ? /^(ANIM_|INST_|HIT_)/ : /^(ANIM_|INST_|HIT_|SCREEN_)/])),
  garden: /^(ANIM_|INST_|SM_env_garden_(fountain_birdbody|pond_duckbody|pond_frogbody|pond_padleaf|potstack_pinwheel))/,
  swings: /^(ANIM_prp_lake_swing_|INST_)/,
  lake: /^(ANIM_|INST_)/,
  chill: /^INST_/,
  farm: /^INST_/,
  bakery: /^INST_/,
};

const UP = new THREE.Vector3(0, 1, 0);

// N: the zone's nodes by name; faces: the legacy canvas faces that just left (zones/sink.js)
export function wireLocal(id, { world, N, faces, anims, mats, root, renderer = null, scenes = [], files = [], consts = null }) {
  // the lookout: island.js hides lookoutTop.leaves while you climb and lookoutTop.hide up top; the
  // zone's crowns (files 1, 2) and roof (file 3) take their places
  if (id === "lookout" && world.lookoutTop) {
    const L = world.lookoutTop;
    const leaves = new THREE.Group();
    leaves.name = "lookout.leaves";
    root.add(leaves);
    scenes.forEach((s, i) => /leaves/.test(files[i]) && leaves.attach(s));
    leaves.visible = !L.faded;
    L.leaves = leaves;
    const roofs = scenes.filter((s, i) => /roof/.test(files[i]));
    for (const r of roofs) r.visible = !L.hidden;
    L.hide = roofs;
  }
  // explicit obstacle tops from the zone's export (no raycast against whatever is drawn yet)
  for (const [name, o] of N) {
    if (!/^COL_circ_/.test(name) || o.userData.tdd_top == null) continue;
    const p = new THREE.Vector3();
    o.getWorldPosition(p);
    const c = world.circles.find((q) => Math.abs(q.x - p.x) < 0.03 && Math.abs(q.z - p.z) < 0.03 && Math.abs(q.r - (o.userData.tdd_r ?? q.r)) < 0.02);
    if (c) c.top = o.userData.tdd_top;
  }
  const hide = HIDE[id];
  if (hide) for (const [name, o] of N) if (hide.test(name)) o.visible = false;
  // a room's inside (fur_room_<id>) brings its own wall lamps: the legacy ones go, now or when furnished
  if (/^rm_/.test(id)) {
    const rid = id.slice(3);
    (world.zoneLampRooms ||= new Set()).add(rid);
    for (const L of world.rooms.get(rid)?.wallLamps || []) L.lamp.visible = false;
  }
  // the signs and boards: each SCREEN_ plane shows the legacy canvas that stood nearest (its
  // material itself, so live redraws, the bakery's design or the chalk menu, carry on)
  const p = new THREE.Vector3();
  const live = [];
  const rm = /^rm_/.test(id);
  for (const [name, o] of N) {
    if ((rm && id !== "rm_bakery") || !/^SCREEN_/.test(name) || !o.isMesh) continue;
    if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
    p.copy(o.geometry.boundingSphere.center).applyMatrix4(o.matrixWorld);
    let best = null;
    let bd = 3;
    for (const f of faces) {
      const d = f.at.distanceTo(p);
      if (d < bd) {
        bd = d;
        best = f;
      }
    }
    if (!best) {
      o.visible = false;
      continue;
    }
    o.material = best.material;
    o.castShadow = false;
    live.push(best.material);
  }
  // (glTF UVs: a canvas drawn the legacy way shows upright with flipY off; redrawn maps too)
  const fix = () => {
    for (const m of live)
      if (m.map && m.map.flipY) {
        m.map.flipY = false;
        m.map.needsUpdate = true;
      }
  };
  fix();
  if (live.length) anims.push(fix);

  if (rm) wireRoom(id.slice(3), { world, N, anims, mats });
  if (id === "games" || id === "trail") {
    // a sign whose front face is tapped (bonk-a-mole, catch the bunnies...) kept its legacy screen
    // (an item hit) at the very spot of the zone's front plane: the zone plane takes over the tap
    // and the legacy face hides, so the two never fight and the canvas shows the zone's way up
    const legacy = [];
    world.scene?.traverse((o) => o.isMesh && o.userData.item && live.includes(o.material) && legacy.push(o));
    const q = new THREE.Vector3();
    for (const [name, o] of N) {
      if (!/^SCREEN_.*front/.test(name) || !o.isMesh || !o.visible) continue;
      p.copy(o.geometry.boundingSphere.center).applyMatrix4(o.matrixWorld);
      for (const l of legacy) {
        if (l.material !== o.material) continue;
        if (!l.geometry.boundingSphere) l.geometry.computeBoundingSphere();
        if (q.copy(l.geometry.boundingSphere.center).applyMatrix4(l.matrixWorld).distanceTo(p) > 0.3) continue;
        o.userData.item = l.userData.item;
        if (Array.isArray(l.userData.item.hits)) l.userData.item.hits.push(o);
        l.visible = false;
      }
    }
    applyConstants(id, world, N, consts);
    if (id === "games") bindGames(world, N);
  }
  if (id === "bakery") {
    const bk = world.rooms.get("bakery")?.bakery;
    const M = bk?.mats || {};
    // the neon name over the door and the chalk menu: their own legacy materials, by name (the
    // nearest-canvas match took the wrong face for the sign, pilot review bug 3)
    for (const [re, m] of [[/^SCREEN_bld_bakery_shell_sign/, M.sign], [/^SCREEN_bld_bakery_aframe_chalk/, M.chalk]])
      for (const [name, o] of N)
        if (re.test(name) && o.isMesh && m) {
          o.material = m;
          o.visible = true;
          if (!live.includes(m)) live.push(m);
        }
    fix();
    // the design floor stops at the walls and the door sill: the zone's floor reached out through the
    // doorway onto the path (the red checker outside the door, the user's report 2026-11-16)
    // (the floor's corners are moved in to the inside faces of the walls, its UVs following, so the
    // picture keeps its scale; no clipping planes, no extra shader)
    const room = world.rooms.get("bakery");
    let floorUvPerM = 0;
    if (room && M.floor) {
      void renderer;
      room.group.updateMatrixWorld(true);
      const HW = 7, HD = 5; // (bakery.js W / 2, D / 2)
      for (const [name, o] of N) if (/bakery_floor/.test(name) && o.isMesh && o.material === M.floor) floorUvPerM = cropToRoom(o, room.group, HW, HD) || floorUvPerM;
    }
    const tints = mats.kitTints?.get("bakery");
    // the awning's design colours on the kit's tint mask (paint = stripe a, trim = stripe b);
    // the paper and floor tile in metres on the zone's UVs
    anims.push(() => {
      if (tints && M.scallopA) {
        tints[0].copy(M.scallopA.color);
        tints[1].copy(M.scallopB.color);
      }
      for (const m of [M.paper, M.floor]) {
        const t = m?.map;
        // (the paper's zone UVs are in tiles already; the floor's are not: its checker keeps the
        // legacy size, two squares every 1.4 m, from how many UV units the floor gives a metre)
        const r = m === M.floor && floorUvPerM ? 1 / (1.4 * floorUvPerM) : 1;
        if (t && (t.wrapS !== THREE.RepeatWrapping || Math.abs(t.repeat.x - r) > 1e-4 || Math.abs(t.repeat.y - r) > 1e-4)) {
          t.wrapS = t.wrapT = THREE.RepeatWrapping;
          t.repeat.set(r, r);
          t.needsUpdate = true;
        }
      }
    });
    // the big cinnamon roll on the roof, swaying (legacy: sin .6t x .15, bob sin 1.2t x .12)
    const roll = N.get("ANIM_bld_bakery_roll_sway__0");
    if (roll) {
      root.attach(roll);
      const q0 = roll.quaternion.clone();
      const p0 = roll.position.clone();
      const z = new THREE.Vector3(0, 0, 1);
      const q = new THREE.Quaternion();
      anims.push((t) => {
        roll.quaternion.copy(q0).multiply(q.setFromAxisAngle(z, Math.sin(t * 0.6) * 0.15));
        roll.position.copy(p0).setY(p0.y + Math.sin(t * 1.2) * 0.12);
      });
    }
  }
  if (id === "picnic") {
    // the three heart balloons on the basket, bobbing as legacy (lowest = k 0)
    const bs = [...N].filter(([n]) => /^ANIM_prp_lake_picnic_balloon/.test(n)).map(([, o]) => o);
    bs.sort((a, b) => a.getWorldPosition(p).y - b.getWorldPosition(new THREE.Vector3()).y);
    const q = new THREE.Quaternion();
    const rest = bs.map((b) => {
      root.attach(b);
      return { b, p: b.position.clone(), q: b.quaternion.clone() };
    });
    anims.push((t) => {
      rest.forEach((r, k) => {
        r.b.position.copy(r.p).setY(r.p.y + Math.sin(t * 1.2 + k) * 0.07);
        r.b.quaternion.copy(r.q).multiply(q.setFromAxisAngle(UP, Math.sin(t * 0.5 + k) * 0.5));
      });
    });
  }
}

// the zone's gameplay constants (zon_<id>.constants.json, packed with the GLBs): the data the collider
// JSON cannot carry. The legacy builders made these very colliders already (frozen world): each one
// is found by where it stands and given the flag / data, so they say the same thing as the export.
// the moles and the straw dummies (zon_games ANIM_ nodes): each zone body joins the nearest legacy
// group, which games.js bobs and fx.js wobbles as before; the legacy meshes stop drawing (they still
// take the rifle's hits: a raycast does not skip hidden meshes)
function bindGames(world, N) {
  const p = new THREE.Vector3();
  const near = (list, at) => list.reduce((b, g) => (!b || g.d < b.d ? g : b), null);
  for (const [name, o] of N) {
    const mole = /^ANIM_act_games_mole_body__\d+$/.test(name);
    const dummy = /^ANIM_act_games_dummy_\d+_body__0$/.test(name);
    if (!mole && !dummy) continue;
    o.getWorldPosition(p);
    const groups = mole ? (world.zoneMoles || []).map((m) => m.group) : world.zoneDummies || [];
    const best = near(groups.map((g) => ({ g, d: Math.hypot(g.getWorldPosition(new THREE.Vector3()).x - p.x, g.getWorldPosition(new THREE.Vector3()).z - p.z) })));
    if (!best || best.d > 1) continue;
    const g = best.g;
    for (const c of g.children) if (c.isMesh) c.visible = false;
    if (mole) {
      // (attached at the mole's rest, down in its hole, whatever the game is doing right now)
      const y = g.position.y;
      g.position.y = -0.6;
      g.updateMatrixWorld(true);
      g.attach(o);
      g.position.y = y;
    } else {
      g.updateMatrixWorld(true);
      g.attach(o);
      o.traverse((c) => (c.userData.target = g.children[0]?.userData.target));
    }
    o.visible = true;
    o.userData.zoneLive = true;
  }
}

// (stats in world.zoneConstStats: applied, and any the export placed where no collider stands)
function applyConstants(id, world, N, c) {
  if (!c) return;
  const st = ((world.zoneConstStats ||= {})[id] = { applied: 0, missing: [] });
  if (id === "games")
    for (const k of c.ball_only || []) {
      // (COL_seg_<k>: its middle, its turn and its length; the world segment with the same ends)
      const o = N.get(`COL_seg_${k}`);
      if (!o) {
        st.missing.push(`seg ${k}: no node`);
        continue;
      }
      const m = new THREE.Vector3();
      o.getWorldPosition(m);
      const len = o.userData.tdd_len ?? 0;
      const s = world.segments.find((g) => Math.hypot((g.ax + g.bx) / 2 - m.x, (g.az + g.bz) / 2 - m.z) < 0.03 && Math.abs(Math.hypot(g.bx - g.ax, g.bz - g.az) - len) < 0.03);
      if (!s) st.missing.push(`seg ${k}`);
      else {
        s.ballOnly = true;
        st.applied++;
      }
    }
  if (id === "trail")
    for (const pad of c.trail_pads || []) {
      const s = (world.solids || []).find((q) => q.base && Math.hypot(q.base.x - pad.base[0], q.base.z - pad.base[2]) < 0.03);
      if (!s) {
        st.missing.push(`pad ${pad.i}`);
        continue;
      }
      // (a plain pad is kind null in the JSON, kind undefined in the game: games.js asks
      // on.kind !== undefined, so it stays undefined)
      if (pad.kind != null) s.kind = pad.kind;
      s.i = pad.i;
      // (the export rounds to 0.1 mm: the legacy base is the same spot, kept unless it is not)
      if (Math.hypot(s.base.x - pad.base[0], s.base.z - pad.base[2]) > 0.001) s.base.set(pad.base[0], pad.base[1], pad.base[2]);
      st.applied++;
    }
}

// a room's inside (zon_room_<id>): its wallpaper, ceiling, floor and rug liners wear the room's own
// legacy canvases (MAT_room_*: the zone's UVs carry the legacy repeat, so the maps repeat once);
// the bakery's counter tops take the design's counter colour (kit tint "paint"); the gallery's
// FRAME_0..7 and the vase socket are checked against the legacy save slots (world.zoneConstStats)
const once1 = (t) => {
  if (!t) return null;
  const c = t.clone();
  c.wrapS = c.wrapT = THREE.RepeatWrapping;
  c.repeat.set(1, 1);
  c.offset.set(0, 0);
  c.needsUpdate = true;
  return c;
};
function wireRoom(rid, { world, N, anims, mats }) {
  const room = world.rooms.get(rid);
  if (!room) return;
  const S = room.roomSurf || {};
  const made = new Map();
  const surf = (n) => {
    if (made.has(n)) return made.get(n);
    let m = null;
    if (n === "MAT_room_paper" && S.paper) m = new THREE.MeshStandardMaterial({ name: n, map: once1(S.paper), roughness: S.paperMat?.roughness ?? 0.9, flatShading: false });
    else if (n === "MAT_room_ceiling" && S.ceil) {
      m = S.ceil.clone();
      m.map = m.emissiveMap = once1(S.ceil.map);
    } else if (n === "MAT_room_floor" && S.floor) m = new THREE.MeshStandardMaterial({ name: n, map: once1(S.floor), roughness: S.floorMat?.roughness ?? 0.85, flatShading: false });
    else if (n === "MAT_room_rug" && S.rug) {
      // (glTF UVs run the other way up: the clock rug's numbers read mirrored on the legacy map)
      m = S.rug.clone();
      const t = S.rug.map.clone();
      t.flipY = !S.rug.map.flipY;
      t.needsUpdate = true;
      m.map = t;
    }
    made.set(n, m);
    return m;
  };
  const st = ((world.zoneConstStats ||= {})[`rm_${rid}`] = { bound: 0, unbound: [] });
  for (const [, o] of N) {
    if (!o.isMesh) continue;
    const n = (o.material?.name || "").replace(/\.\d+$/, "");
    if (!/^MAT_room_/.test(n)) continue;
    const m = surf(n);
    if (m) {
      o.material = m;
      st.bound++;
    } else {
      o.visible = false;
      st.unbound.push(n);
    }
  }
  // the bakery: the counter, island and café-table tops in the design's counter colour
  if (rid === "bakery") {
    const M = room.bakery?.mats || {};
    const tints = mats.kitTints?.get("interior");
    if (tints && M.counter) anims.push(() => tints[0].copy(M.counter.color));
  }
  const p = new THREE.Vector3();
  // the 8 gallery frames keep their save index: FRAME_<k> stands where the legacy frame k hangs
  if (room.galleryFrames?.length) {
    let worst = 0;
    const q = new THREE.Vector3();
    room.galleryFrames.forEach((pic, k) => {
      const f = N.get(`FRAME_${k}`);
      if (!f) return (worst = Infinity);
      f.getWorldPosition(p);
      pic.getWorldPosition(q);
      worst = Math.max(worst, Math.hypot(p.x - q.x, p.z - q.z));
    });
    st.frames = { n: room.galleryFrames.length, worstM: +worst.toFixed(3) };
  }
  // the vase: bouquets.js's own (save index 9 + room), standing at the zone's SOCK_vase
  const sock = N.get("SOCK_vase");
  if (sock) {
    sock.getWorldPosition(p).setY(0);
    const vase = world.interactables.find((it) => /^vase-/.test(it.id) && it.pos.distanceTo(p) < 0.6);
    st.vase = vase ? vase.id : "none near";
  }
}

// a flat floor cut to a room's inside: its vertices (in the room's frame) clamped to the room's half
// sizes, its UVs worked out again from the same straight-line map position -> UV the export used
function cropToRoom(o, roomGroup, hw, hd) {
  const g = o.geometry;
  const pos = g.attributes.position;
  const uv = g.attributes.uv;
  if (!pos || !uv) return;
  o.updateWorldMatrix(true, false);
  const toRoom = new THREE.Matrix4().copy(roomGroup.matrixWorld).invert().multiply(o.matrixWorld);
  const back = new THREE.Matrix4().copy(toRoom).invert();
  const v = new THREE.Vector3();
  const pts = [];
  for (let i = 0; i < pos.count; i++) pts.push(v.fromBufferAttribute(pos, i).applyMatrix4(toRoom).clone());
  // least squares: u = a x + b z + c, the same for v
  const fit = (get) => {
    let sxx = 0, sxz = 0, szz = 0, sx = 0, sz = 0, n = 0, sxu = 0, szu = 0, su = 0;
    pts.forEach((p, i) => {
      const u = get(i);
      sxx += p.x * p.x; sxz += p.x * p.z; szz += p.z * p.z; sx += p.x; sz += p.z; n++;
      sxu += p.x * u; szu += p.z * u; su += u;
    });
    const A = new THREE.Matrix3().set(sxx, sxz, sx, sxz, szz, sz, sx, sz, n);
    if (Math.abs(A.determinant()) < 1e-9) return null;
    return new THREE.Vector3(sxu, szu, su).applyMatrix3(A.invert());
  };
  const fu = fit((i) => uv.getX(i));
  const fv = fit((i) => uv.getY(i));
  if (!fu || !fv) return;
  const p2 = g.attributes.position.clone();
  const uv2 = uv.clone();
  pts.forEach((p, i) => {
    p.x = Math.max(-hw, Math.min(hw, p.x));
    p.z = Math.max(-hd, Math.min(hd, p.z));
    uv2.setXY(i, fu.x * p.x + fu.y * p.z + fu.z, fv.x * p.x + fv.y * p.z + fv.z);
    const w = p.clone().applyMatrix4(back);
    p2.setXYZ(i, w.x, w.y, w.z);
  });
  const ng = g.clone();
  ng.setAttribute("position", p2);
  ng.setAttribute("uv", uv2);
  ng.computeBoundingSphere();
  ng.computeBoundingBox();
  o.geometry = ng;
  return Math.hypot(fu.x, fu.y);
}
