// The clip libraries in the game: the zones runtime loads the carriers (chr_avatar_clips, the animals'
// and the rides' and the ambient props' clips) after the kits and registers them here; each rig binds the
// first frame it finds its own. Under zones=legacy, or until a carrier is in, its rigs keep their
// procedural motion.
import { ClipLib } from "./runtime.js";

// [pack dir, carrier] in load order (the pets first: they are the nearest)
export const CARRIERS = [
  ["animals/", "ani_pet_cat_clips"],
  ["animals/", "ani_pet_bunny_clips"],
  ["clips/", "veh_unicorn_clips"],
  ["clips/", "veh_scooter_clips"],
  ["clips/", "env_ambient_clips"],
  ...["cow", "goat", "sheep", "hen", "chick", "deer", "duck", "duckling", "frog", "hedgehog", "bee", "butterfly", "dookie"].map((n) => ["animals/", `ani_${n}_clips`]),
  ["clips/", "prp_lake_swing_clips"],
  ["clips/", "bld_balloon_ride_clips"],
  ["clips/", "act_coaster_car_clips"],
];

const libs = new Map();
export const clipLib = (asset) => libs.get(asset) || null;
export function setClipsFromGLTF(gltf, asset) {
  try {
    libs.set(asset, ClipLib.fromGLTF(gltf, asset));
  } catch (e) {
    console.warn("clips", asset, e);
  }
}
export const clipStats = () => [...libs.keys()];
export const resetClips = () => libs.clear();
